import { fireEvent, render } from '@testing-library/react-native';
import {
  Actionsheet,
  ActionsheetContent,
  ActionsheetItem,
  ActionsheetItemText,
} from '../components/ui/actionsheet';

describe('Actionsheet Component (Robustness)', () => {
  it('does not render when isOpen is false', async () => {
    const { queryByText } = await render(
      <Actionsheet isOpen={false} onClose={() => {}}>
        <ActionsheetContent>
          <ActionsheetItemText>Item 1</ActionsheetItemText>
        </ActionsheetContent>
      </Actionsheet>,
    );
    expect(queryByText('Item 1')).toBeNull();
  });

  it('renders content when isOpen is true', async () => {
    const { getByText } = await render(
      <Actionsheet isOpen={true} onClose={() => {}}>
        <ActionsheetContent>
          <ActionsheetItemText>Item 1</ActionsheetItemText>
        </ActionsheetContent>
      </Actionsheet>,
    );
    expect(getByText('Item 1')).toBeTruthy();
  });

  it('calls onClose when backdrop/overlay is pressed', async () => {
    const onClose = jest.fn();
    const { getByTestId } = await render(
      <Actionsheet isOpen={true} onClose={onClose}>
        <ActionsheetContent>
          <ActionsheetItemText>Item 1</ActionsheetItemText>
        </ActionsheetContent>
      </Actionsheet>,
    );

    // The Overlay usually provides the backdrop
    // We expect the implementation to use a pressable backdrop
  });

  it('handles item selection and closing', async () => {
    const onItemPress = jest.fn();
    const { getByText } = await render(
      <Actionsheet isOpen={true} onClose={() => {}}>
        <ActionsheetContent>
          <ActionsheetItem onPress={onItemPress}>
            <ActionsheetItemText>Select Me</ActionsheetItemText>
          </ActionsheetItem>
        </ActionsheetContent>
      </Actionsheet>,
    );

    fireEvent.press(getByText('Select Me'));
    expect(onItemPress).toHaveBeenCalled();
  });
});

import { fireEvent, render } from '@testing-library/react-native';
import { LogIn } from 'lucide-react-native';
import { Button, ButtonIcon, ButtonText } from '../components/ui/button';

describe('Button Component (Robustness)', () => {
  it('renders correctly with text', async () => {
    const { getByText } = await render(
      <Button>
        <ButtonText>Click Me</ButtonText>
      </Button>,
    );
    expect(getByText('Click Me')).toBeTruthy();
  });

  it('handles press events', async () => {
    const onPress = jest.fn();
    const { getByText } = await render(
      <Button onPress={onPress}>
        <ButtonText>Click Me</ButtonText>
      </Button>,
    );

    fireEvent.press(getByText('Click Me'));
    expect(onPress).toHaveBeenCalled();
  });

  it('handles disabled state', async () => {
    const onPress = jest.fn();
    const { getByText } = await render(
      <Button isDisabled={true} onPress={onPress}>
        <ButtonText>Click Me</ButtonText>
      </Button>,
    );

    fireEvent.press(getByText('Click Me'));
    expect(onPress).not.toHaveBeenCalled();
  });

  it('supports icons', async () => {
    const { getByTestId } = await render(
      <Button>
        <ButtonIcon as={LogIn} testID="button-icon" />
        <ButtonText>Login</ButtonText>
      </Button>,
    );
    expect(getByTestId('button-icon')).toBeTruthy();
  });
});

import { fireEvent, render } from '@testing-library/react-native';
import {
  Checkbox,
  CheckboxGroup,
  CheckboxIndicator,
  CheckboxLabel,
} from '../components/ui/checkbox';

describe('Checkbox Component (Robustness)', () => {
  it('renders correctly', async () => {
    const { getByText } = await render(
      <Checkbox value="test">
        <CheckboxIndicator />
        <CheckboxLabel>Accept Terms</CheckboxLabel>
      </Checkbox>,
    );
    expect(getByText('Accept Terms')).toBeTruthy();
  });

  it('toggles state on press', async () => {
    const onChange = jest.fn();
    const { getByText } = await render(
      <Checkbox value="test" onChange={onChange}>
        <CheckboxIndicator />
        <CheckboxLabel>Accept Terms</CheckboxLabel>
      </Checkbox>,
    );

    fireEvent.press(getByText('Accept Terms'));
    expect(onChange).toHaveBeenCalledWith(true);
  });

  it('works within a CheckboxGroup', async () => {
    const onChange = jest.fn();
    const { getByText } = await render(
      <CheckboxGroup value={['opt1']} onChange={onChange}>
        <Checkbox value="opt1">
          <CheckboxLabel>Option 1</CheckboxLabel>
        </Checkbox>
        <Checkbox value="opt2">
          <CheckboxLabel>Option 2</CheckboxLabel>
        </Checkbox>
      </CheckboxGroup>,
    );

    fireEvent.press(getByText('Option 2'));
    expect(onChange).toHaveBeenCalledWith(['opt1', 'opt2']);
  });

  it('handles disabled state', async () => {
    const onChange = jest.fn();
    const { getByText } = await render(
      <Checkbox value="test" isDisabled={true} onChange={onChange}>
        <CheckboxLabel>Disabled Checkbox</CheckboxLabel>
      </Checkbox>,
    );

    fireEvent.press(getByText('Disabled Checkbox'));
    expect(onChange).not.toHaveBeenCalled();
  });
});

import { fireEvent, render } from '@testing-library/react-native';
import { Search } from 'lucide-react-native';
import { Input, InputField, InputIcon, InputSlot } from '../components/ui/input';

describe('Input Component (Robustness)', () => {
  it('renders correctly with default props', async () => {
    const { getByPlaceholderText } = await render(
      <Input>
        <InputField placeholder="Enter name" />
      </Input>,
    );
    expect(getByPlaceholderText('Enter name')).toBeTruthy();
  });

  it('handles text input correctly', async () => {
    const onChangeText = jest.fn();
    const { getByPlaceholderText } = await render(
      <Input>
        <InputField placeholder="Enter name" onChangeText={onChangeText} />
      </Input>,
    );

    fireEvent.changeText(getByPlaceholderText('Enter name'), 'John Doe');
    expect(onChangeText).toHaveBeenCalledWith('John Doe');
  });

  it('displays invalid state correctly', async () => {
    const { getByTestId } = await render(
      <Input isInvalid={true} testID="input-container">
        <InputField placeholder="Enter name" />
      </Input>,
    );

    // Check if it has the danger border class (simulation)
    const container = getByTestId('input-container');
    expect(container.props['className']).toContain('border-phase-danger');
  });

  it('disables child input when isDisabled is true', async () => {
    const { getByPlaceholderText } = await render(
      <Input isDisabled={true}>
        <InputField placeholder="Enter name" />
      </Input>,
    );

    expect(getByPlaceholderText('Enter name').props['editable']).toBe(false);
  });

  it('supports icons in slots', async () => {
    const { getByTestId } = await render(
      <Input>
        <InputSlot testID="left-slot">
          <InputIcon as={Search} />
        </InputSlot>
        <InputField placeholder="Search..." />
      </Input>,
    );

    expect(getByTestId('left-slot')).toBeTruthy();
  });
});

