import { fireEvent, render } from '@testing-library/react-native';
import { Radio, RadioGroup, RadioIndicator, RadioLabel } from '../components/ui/radio';

describe('Radio Component (Robustness)', () => {
  it('renders correctly', async () => {
    const { getByText } = await render(
      <Radio value="opt1">
        <RadioIndicator />
        <RadioLabel>Option 1</RadioLabel>
      </Radio>,
    );
    expect(getByText('Option 1')).toBeTruthy();
  });

  it('works within a RadioGroup', async () => {
    const onChange = jest.fn();
    const { getByText } = await render(
      <RadioGroup value="opt1" onChange={onChange}>
        <Radio value="opt1">
          <RadioLabel>Option 1</RadioLabel>
        </Radio>
        <Radio value="opt2">
          <RadioLabel>Option 2</RadioLabel>
        </Radio>
      </RadioGroup>,
    );

    fireEvent.press(getByText('Option 2'));
    expect(onChange).toHaveBeenCalledWith('opt2');
  });

  it('handles disabled state', async () => {
    const _onChange = jest.fn();
    const { getByText } = await render(
      <Radio value="test" isDisabled={true}>
        <RadioLabel>Disabled Radio</RadioLabel>
      </Radio>,
    );

    fireEvent.press(getByText('Disabled Radio'));
    // Since Radio takes value/onPress etc., implementation should block it.
  });
});

import { fireEvent, render, waitFor } from '@testing-library/react-native';
import { ChevronDown } from 'lucide-react-native';
import React from 'react';
import {
  Select,
  SelectBackdrop,
  SelectContent,
  SelectDragIndicator,
  SelectDragIndicatorWrapper,
  SelectIcon,
  SelectInput,
  SelectItem,
  SelectPortal,
  SelectTrigger,
} from '../components/ui/select';

/**
 * Proactive Component Testing
 * Defines the contract for the hardened Select primitive.
 */

// Simple wrapper to handle state in tests
const SelectTest = ({ onValueChange }: { onValueChange?: (val: string) => void }) => {
  const [value, setValue] = React.useState('');

  const handleValueChange = (val: string) => {
    setValue(val);
    onValueChange?.(val);
  };

  return (
    <Select value={value} onValueChange={handleValueChange}>
      <SelectTrigger>
        <SelectInput placeholder="Select option" value={value} />
        <SelectIcon as={ChevronDown} />
      </SelectTrigger>
      <SelectPortal>
        <SelectBackdrop />
        <SelectContent>
          <SelectDragIndicatorWrapper>
            <SelectDragIndicator />
          </SelectDragIndicatorWrapper>
          <SelectItem label="Option 1" value="opt1" />
          <SelectItem label="Option 2" value="opt2" />
        </SelectContent>
      </SelectPortal>
    </Select>
  );
};

describe('Select Component (Robustness)', () => {
  it('renders trigger with placeholder initially', async () => {
    const { getByText } = await render(<SelectTest />);
    expect(getByText('Select option')).toBeTruthy();
  });

  it('opens content when trigger is pressed', async () => {
    const { getByText } = await render(<SelectTest />);

    fireEvent.press(getByText('Select option'));

    await waitFor(() => {
      expect(getByText('Option 1')).toBeTruthy();
      expect(getByText('Option 2')).toBeTruthy();
    });
  });

  it('selects an option and updates the trigger text', async () => {
    const onValueChange = jest.fn();
    const { getByText } = await render(<SelectTest onValueChange={onValueChange} />);

    fireEvent.press(getByText('Select option'));
    fireEvent.press(getByText('Option 1'));

    expect(onValueChange).toHaveBeenCalledWith('opt1');
    expect(getByText('Option 1')).toBeTruthy();
  });

  it('closes the content after selection', async () => {
    const { getByText, queryByText } = await render(<SelectTest />);

    fireEvent.press(getByText('Select option'));
    fireEvent.press(getByText('Option 1'));

    await waitFor(() => {
      expect(queryByText('Option 2')).toBeNull();
    });
  });

  it('handles disabled state', async () => {
    const { getByText, queryByText } = await render(
      <Select isDisabled={true}>
        <SelectTrigger>
          <SelectInput placeholder="Select option" />
        </SelectTrigger>
        <SelectPortal>
          <SelectItem label="Option 1" value="opt1" />
        </SelectPortal>
      </Select>,
    );

    fireEvent.press(getByText('Select option'));
    expect(queryByText('Option 1')).toBeNull();
  });
});

import { act, fireEvent, render } from '@testing-library/react-native';
import { Pressable, Text } from '../primitives';
import { ToastProvider, useToast } from '../providers/ToastProvider';

const TestComponent = ({ message = 'Hello', type = 'info' as any }) => {
  const { showToast } = useToast();
  return (
    <Pressable onPress={() => showToast({ message, type, duration: 100 })}>
      <Text>Trigger Toast</Text>
    </Pressable>
  );
};

describe('Toast System Logic (2026 Standard)', () => {
  it('triggers and shows a toast message via hook', async () => {
    const { getByText, queryByText } = await render(
      <ToastProvider>
        <TestComponent message="Test Success" />
      </ToastProvider>,
    );

    expect(queryByText('Test Success')).toBeNull();

    fireEvent.press(getByText('Trigger Toast'));

    expect(getByText('Test Success')).toBeTruthy();
  });

  it('automatically removes toast after duration', async () => {
    jest.useFakeTimers();
    const { getByText, queryByText } = await render(
      <ToastProvider>
        <TestComponent message="Timed Toast" />
      </ToastProvider>,
    );

    fireEvent.press(getByText('Trigger Toast'));
    expect(getByText('Timed Toast')).toBeTruthy();

    act(() => {
      jest.advanceTimersByTime(200);
    });

    expect(queryByText('Timed Toast')).toBeNull();
    jest.useRealTimers();
  });
});

const { resolveClassicTokens, resolvePhaseTokens } = require('../theme/Theme');

describe('resolvePhaseTokens', () => {
  it('returns scene tokens for night/dark', () => {
    const tokens = resolvePhaseTokens('night', true);

    expect(tokens.scene.world.bg).toBe('#0F131C');
    expect(tokens.scene.chrome.bg).toBe(tokens.glass.surface.bg);
    expect(tokens.scene.elevated.bg).toBe(tokens.glass.modal.bg);
    expect(tokens.text.onWorld).toBe('#FCF9F2');
    expect(tokens.accent.action).toBe('#FDD925');
  });

  it('returns scene tokens for morning/light', () => {
    const tokens = resolvePhaseTokens('morning', false);

    expect(tokens.scene.world.bg).toBe('#F5EDD6');
    expect(tokens.scene.canvas.bg).toBe('#DCFCE7');
    expect(tokens.text.onCanvas).toBe('#2A2318');
    expect(tokens.accent.action).toBe('#8BBF7A');
    expect(tokens.text.onAccent).toBe(tokens.text.inverse);
  });

  it('all six phases resolve without throwing in both worlds', () => {
    const phases = ['predawn', 'dawn', 'morning', 'afternoon', 'dusk', 'night'];

    phases.forEach((phase) => {
      expect(() => resolvePhaseTokens(phase, false)).not.toThrow();
      expect(() => resolvePhaseTokens(phase, true)).not.toThrow();
    });
  });

  it('classic tokens project into the same scene contract', () => {
    const lightClassic = resolveClassicTokens(false);
    const darkClassic = resolveClassicTokens(true);

    expect(lightClassic.scene.canvas.bg).toBe('#FAF7ED');
    expect(lightClassic.text.onCanvas).toBe('#2A2318');
    expect(darkClassic.scene.world.bg).toBe('#0F131C');
    expect(darkClassic.text.onWorld).toBe('#FCF9F2');
  });
});

