import { Trophy } from 'lucide-react-native';
import { useCallback, useEffect } from 'react';
import { Dimensions } from 'react-native';
import Animated, {
  runOnJS,
  useAnimatedStyle,
  useSharedValue,
  withSpring,
  withTiming,
} from 'react-native-reanimated';
import { Box, Center, Text, VStack } from '../gluestack';

const { width } = Dimensions.get('window');

interface AchievementUnlockOverlayProps {
  title: string;
  visible: boolean;
  onHide: () => void;
}

/**
 * AchievementUnlockOverlay
 *
 * A high-impact, temporary overlay for celebrating progress.
 * Hardened v3 implementation with NativeWind.
 */
export default function AchievementUnlockOverlay({
  title,
  visible,
  onHide,
}: AchievementUnlockOverlayProps) {
  const translateY = useSharedValue(-200);
  const scale = useSharedValue(0.8);
  const opacity = useSharedValue(0);

  const performHide = useCallback(() => {
    opacity.value = withTiming(0, { duration: 300 });
    scale.value = withTiming(0.8, { duration: 300 });
    translateY.value = withTiming(-200, { duration: 400 }, (finished) => {
      if (finished) {
        runOnJS(onHide)();
      }
    });
  }, [opacity, scale, translateY, onHide]);

  useEffect(() => {
    if (!visible) return;

    // Animate In
    translateY.value = withSpring(60, { damping: 12 });
    opacity.value = withTiming(1, { duration: 400 });
    scale.value = withSpring(1, { damping: 10 });

    // Auto Hide after 4 seconds
    const timer = setTimeout(() => {
      performHide();
    }, 4000);

    return () => clearTimeout(timer);
  }, [visible, translateY, scale, opacity, performHide]);

  const animatedStyle = useAnimatedStyle(() => ({
    transform: [{ translateY: translateY.value }, { scale: scale.value }] as any,
    opacity: opacity.value,
  }));

  if (!visible) return null;

  return (
    <Animated.View
      style={[
        {
          position: 'absolute',
          top: 0,
          left: 0,
          right: 0,
          alignItems: 'center',
          zIndex: 1000,
        },
        animatedStyle,
      ]}
    >
      <Box
        className="bg-ink border-2 border-templeGold rounded-generous p-6 shadow-2xl items-center"
        style={{
          width: width * 0.85,
          shadowColor: '#FDD925',
          shadowOffset: { width: 0, height: 0 },
          shadowOpacity: 0.5,
          shadowRadius: 15,
          elevation: 20,
        }}
      >
        <VStack className="items-center gap-2">
          <Center className="p-3 bg-templeGold/20 rounded-full mb-2">
            <Trophy color="#FDD925" size={40} />
          </Center>

          <Text className="text-templeGold font-bold text-lg uppercase tracking-wider">
            Achievement Unlocked!
          </Text>

          <Text className="text-sacredWhite font-bold text-center text-xl">{title}</Text>

          <Text className="text-starlightGray text-sm text-center">
            Your discovery adds to the sanctuary.
          </Text>
        </VStack>
      </Box>
    </Animated.View>
  );
}

import { Runtime } from '@repo/core/native';

import React, { useEffect } from 'react';
import { View } from '../primitives';
import Animated, {
  Easing,
  useAnimatedStyle,
  useSharedValue,
  withDelay,
  withTiming,
} from 'react-native-reanimated';

interface BreathAnimationProps {
  children: React.ReactNode;
  delay?: number;
  duration?: number;
  direction?: 'up' | 'down' | 'none';
}

interface AnimatedContentProps {
  children: React.ReactNode;
  delay: number;
  duration: number;
  direction: 'up' | 'down' | 'none';
}

/**
 * AnimatedContent - Internal component that owns the Reanimated shared values.
 * Only mounted when the JSI runtime is confirmed ready, preventing Bridgeless crashes.
 */
const AnimatedContent = ({ children, delay, duration, direction }: AnimatedContentProps) => {
  const opacity = useSharedValue(0);
  const translateY = useSharedValue(direction === 'up' ? 20 : direction === 'down' ? -20 : 0);

  useEffect(() => {
    opacity.value = withDelay(delay, withTiming(1, { duration, easing: Easing.out(Easing.quad) }));
    translateY.value = withDelay(
      delay,
      withTiming(0, { duration, easing: Easing.out(Easing.quad) }),
    );
  }, [delay, duration, translateY, opacity]);

  const animatedStyle = useAnimatedStyle(() => ({
    opacity: opacity.value,
    transform: [{ translateY: translateY.value }],
  }));

  return <Animated.View style={animatedStyle}>{children}</Animated.View>;
};

/**
 * BreathAnimation - Implements the "Breath-like Motion" from TAIL_FIN.md
 * Provides a staggered, smooth entry for UI elements.
 * Defers JSI-heavy Reanimated hooks into a child component that is only
 * rendered once the runtime is ready, preventing Bridgeless-mode crashes.
 */
export const BreathAnimation = ({
  children,
  delay = 0,
  duration = 500,
  direction = 'up',
}: BreathAnimationProps) => {
  const [isReady, setIsReady] = React.useState(Runtime.isReady());

  useEffect(() => {
    if (isReady) return;
    return Runtime.onReady(() => setIsReady(true));
  }, [isReady]);

  if (!isReady) {
    return <View>{children}</View>;
  }

  return (
    <AnimatedContent delay={delay} duration={duration} direction={direction}>
      {children}
    </AnimatedContent>
  );
};

/**
 * BREATHING LOADER - Pulsing Circle Animation
 *
 * A simple loader component with a breathing animation:
 * - Pulsing circle that scales from 0.8 to 1.0
 * - 1.5 second infinite loop cycle
 * - Centered in parent container
 * - Customizable size and color
 * - Respects reduced-motion accessibility preference
 *
 * Philosophy: Calm, meditative loading state that doesn't distract
 */

import { type FC, useEffect } from 'react';
import { useTranslation } from 'react-i18next';
import { StyleSheet } from 'react-native';
import { View } from '../primitives';
import Animated, {
  Easing,
  useAnimatedStyle,
  useSharedValue,
  withRepeat,
  withTiming,
} from 'react-native-reanimated';
import { useAccessibility } from '../hooks/useAccessibility';
import { Theme } from '../theme/Theme';

interface BreathingLoaderProps {
  size?: number;
  color?: string;
}

const DEFAULT_SIZE = 50;
const DEFAULT_COLOR = Theme.colors.sanctuarySaffron;
const SCALE_MIN = 0.8;
const SCALE_MAX = 1.0;
const ANIMATION_DURATION = 1500;

const BreathingLoader: FC<BreathingLoaderProps> = ({
  size = DEFAULT_SIZE,
  color = DEFAULT_COLOR,
}) => {
  const { isReduceMotionEnabled } = useAccessibility();
  const { t } = useTranslation();
  const scale = useSharedValue(SCALE_MIN);

  useEffect(() => {
    if (isReduceMotionEnabled) {
      scale.value = SCALE_MAX;
      return;
    }
    scale.value = withRepeat(
      withTiming(SCALE_MAX, {
        duration: ANIMATION_DURATION,
        easing: Easing.inOut(Easing.ease),
      }),
      -1,
      true,
    );
  }, [isReduceMotionEnabled, scale]);

  const animatedStyle = useAnimatedStyle(() => ({
    transform: [{ scale: scale.value }],
  }));

  return (
    <View
      style={styles.container}
      accessible={true}
      accessibilityRole="progressbar"
      accessibilityLabel={t('accessibility.loading')}
    >
      <Animated.View
        style={[
          styles.circle,
          {
            width: size,
            height: size,
            borderRadius: size / 2,
            backgroundColor: color,
          },
          animatedStyle,
        ]}
      />
    </View>
  );
};

const styles = StyleSheet.create({
  container: {
    justifyContent: 'center',
    alignItems: 'center',
  },
  circle: {},
});

export default BreathingLoader;

import { VStack } from '../gluestack';
import PositiveInvitation from './PositiveInvitation';
import { SanctuaryButton } from './SanctuaryButton';

export interface CitizenGateProps {
  context?: 'self' | 'library' | 'classroom' | 'community' | 'profile' | 'general';
  title?: string;
  description?: string;
  actionLabel?: string;
  onAction: () => void;
  secondaryLabel?: string;
  onSecondary?: () => void;
}

export default function CitizenGate({
  context = 'general',
  title,
  description,
  actionLabel,
  onAction,
  secondaryLabel,
  onSecondary,
}: CitizenGateProps) {
  const mappedContext = context === 'profile' || context === 'general' ? 'self' : (context as any);

  return (
    <VStack className="gap-4 w-full items-center">
      <PositiveInvitation
        title={title}
        description={description}
        type="guest"
        context={mappedContext}
        actionLabel={actionLabel}
        onAction={onAction}
      />
      {secondaryLabel && onSecondary && (
        <SanctuaryButton
          variant="outline"
          action="secondary"
          onPress={onSecondary}
          className="px-8"
        >
          {secondaryLabel}
        </SanctuaryButton>
      )}
    </VStack>
  );
}

/**
 * COLLECTION CARD - Netflix-Style Cover Art Card
 *
 * Displays a ResourceCollection as a visually rich cover-art card with:
 * - Optional thumbnail image background
 * - Gradient overlay for text legibility
 * - Subject tag badge, item count badge, and creator name
 * - "Verified" badge when the collection is verified
 * - "Pull to Desk" bookmark action
 *
 * Philosophy: Engaging, visual, and curated ΓÇö inspired by streaming services.
 */

import { LinearGradient } from 'expo-linear-gradient';
import { BadgeCheck, Bookmark, BookOpen } from 'lucide-react-native';
import { ImageBackground } from 'react-native';
import { Pressable } from '../primitives';
import { Box, HStack, Text, VStack } from '../gluestack';

// ============================================================================
// CONSTANTS
// ============================================================================

const CARD_WIDTH = 180;
const CARD_HEIGHT = 220;

// ============================================================================
// TYPES
// ============================================================================

export interface CollectionCardProps<T = any> {
  title: string;
  creator: string;
  resourceCount: number;
  subjectTag: string;
  thumbnailUrl?: string;
  verified?: boolean;
  contextData?: T;
  onPress?: (contextData: T) => void;
  onPullToDesk?: (contextData: T) => void;
  className?: string;
}

// ============================================================================
// COMPONENT
// ============================================================================

export function CollectionCard<T = any>({
  title,
  creator,
  resourceCount,
  subjectTag,
  thumbnailUrl,
  verified = false,
  contextData,
  onPress,
  onPullToDesk,
  className,
}: CollectionCardProps<T>) {
  const cardContent = (
    <Box
      style={{ width: CARD_WIDTH, height: CARD_HEIGHT }}
      className={`rounded-3xl overflow-hidden bg-phase-surface shadow-md ${className || ''}`}
    >
      {thumbnailUrl ? (
        <ImageBackground source={{ uri: thumbnailUrl }} className="flex-1" resizeMode="cover">
          <CardOverlay
            title={title}
            creator={creator}
            resourceCount={resourceCount}
            subjectTag={subjectTag}
            verified={verified}
            onPullToDesk={onPullToDesk ? () => onPullToDesk(contextData as T) : undefined}
          />
        </ImageBackground>
      ) : (
        <VStack className="flex-1 items-center justify-center bg-phase-surface">
          <BookOpen className="text-phase-accent opacity-50" size={44} />
          <CardOverlay
            title={title}
            creator={creator}
            resourceCount={resourceCount}
            subjectTag={subjectTag}
            verified={verified}
            onPullToDesk={onPullToDesk ? () => onPullToDesk(contextData as T) : undefined}
            absolute
          />
        </VStack>
      )}
    </Box>
  );

  if (onPress) {
    return (
      <Pressable onPress={() => onPress(contextData as T)} className="rounded-3xl mr-4">
        {cardContent}
      </Pressable>
    );
  }
  return <Box className="rounded-3xl mr-4">{cardContent}</Box>;
}

// ============================================================================
// INTERNAL: OVERLAY
// ============================================================================

interface OverlayProps {
  title: string;
  creator: string;
  resourceCount: number;
  subjectTag: string;
  verified: boolean;
  onPullToDesk?: () => void;
  absolute?: boolean;
}

function CardOverlay({
  title,
  creator,
  resourceCount,
  subjectTag,
  verified,
  onPullToDesk,
  absolute = false,
}: OverlayProps) {
  return (
    <VStack
      className={`
                flex-1 justify-between p-3
                ${absolute ? 'absolute inset-0' : ''}
            `}
    >
      {/* Top Row */}
      <HStack className="items-center justify-between">
        <Box className="bg-phase-accent px-2 py-1 rounded-md">
          <Text className="text-[10px] font-bold text-white tracking-widest uppercase">
            {subjectTag}
          </Text>
        </Box>
        {verified && (
          <HStack className="items-center gap-1 bg-black/40 px-2 py-1 rounded-md border border-white/10">
            <BadgeCheck className="text-phase-success" size={12} />
            <Text className="text-[10px] font-semibold text-phase-success">Verified</Text>
          </HStack>
        )}
      </HStack>

      {/* Bottom Gradient with title, creator, count */}
      <LinearGradient
        colors={['transparent', 'rgba(0,0,0,0.6)', 'rgba(0,0,0,0.9)']}
        className="absolute left-0 right-0 bottom-0 p-3 pt-8"
      >
        <VStack className="gap-1">
          <Text className="text-sm font-bold text-white leading-5" numberOfLines={2}>
            {title}
          </Text>
          <Text className="text-[11px] text-white/70" numberOfLines={1}>
            {creator}
          </Text>

          <HStack className="items-center justify-between mt-1">
            <HStack className="items-center gap-1 bg-white/10 px-2 py-1 rounded-md border border-white/5">
              <BookOpen className="text-white/60" size={11} />
              <Text className="text-[11px] font-semibold text-white/80">{resourceCount} Items</Text>
            </HStack>

            {onPullToDesk && (
              <Pressable
                onPress={onPullToDesk}
                className="p-2 bg-phase-accent/20 rounded-md border border-phase-accent"
                hitSlop={8}
              >
                <Bookmark className="text-phase-accent" size={14} />
              </Pressable>
            )}
          </HStack>
        </VStack>
      </LinearGradient>
    </VStack>
  );
}

import { Platform } from 'react-native';
import { BarChart3, Clock, Image as ImageIcon, Lock, Mic, Plus, Trash2, Users, X } from '../icons';
import {
  Box,
  Button,
  ButtonText,
  HStack,
  Icon,
  Image,
  Input,
  InputField,
  Pressable,
  ScrollView,
  Spinner,
  Switch,
  Text,
  Textarea,
  TextareaInput,
  VStack,
} from '../primitives';
import SanctuaryModal from './SanctuaryModal';

export interface Tag {
  id: string;
  label: string;
}

export interface ComposerProps {
  isOpen: boolean;
  onClose: () => void;
  title?: string;
  submitLabel?: string;
  placeholder?: string;

  // State
  content: string;
  isSubmitting: boolean;
  isUploading?: boolean;
  selectedImage: string | null;
  selectedTags: string[];
  tags?: Tag[];

  // Poll State (Optional)
  isPollMode: boolean;
  pollOptions: string[];
  pollIsAnonymous: boolean;
  pollAllowMultiple: boolean;
  pollDurationHours: number | null;
  pollCustomEndsAt: string;
  showCustomDate: boolean;
  durationPresets?: { label: string; hours: number | null }[];

  // Features
  allowPolls?: boolean;
  allowMedia?: boolean;
  allowTags?: boolean;

  // Handlers
  onContentChange: (val: string) => void;
  onToggleTag: (id: string) => void;
  onPickImage: () => void;
  onRemoveImage: () => void;
  onTogglePollMode: () => void;
  onAddPollOption: () => void;
  onUpdatePollOption: (idx: number, val: string) => void;
  onRemovePollOption: (idx: number) => void;
  onSetPollDuration: (hours: number | null) => void;
  onSetShowCustomDate: (show: boolean) => void;
  onSetCustomDate: (val: string) => void;
  onSetPollAnonymous: (val: boolean) => void;
  onSetPollMultiple: (val: boolean) => void;
  onSubmit: () => void;
}

const DEFAULT_PRESETS = [
  { label: 'No end', hours: null },
  { label: '1 h', hours: 1 },
  { label: '24 h', hours: 24 },
  { label: '3 d', hours: 72 },
  { label: '7 d', hours: 168 },
];

export function ContentComposer(props: ComposerProps) {
  const {
    isOpen,
    onClose,
    title = 'Create Content',
    submitLabel = 'Post',
    placeholder = "What's on your mind?",
    content,
    isSubmitting,
    isUploading,
    selectedImage,
    selectedTags,
    tags = [],
    isPollMode,
    pollOptions,
    pollIsAnonymous,
    pollAllowMultiple,
    pollDurationHours,
    pollCustomEndsAt,
    showCustomDate,
    durationPresets = DEFAULT_PRESETS,
    allowPolls = true,
    allowMedia = true,
    allowTags = true,
    onContentChange,
    onToggleTag,
    onPickImage,
    onRemoveImage,
    onTogglePollMode,
    onAddPollOption,
    onUpdatePollOption,
    onRemovePollOption,
    onSetPollDuration,
    onSetShowCustomDate,
    onSetCustomDate,
    onSetPollAnonymous,
    onSetPollMultiple,
    onSubmit,
  } = props;

  const footer = (
    <Button
      onPress={onSubmit}
      isDisabled={(!content.trim() && !selectedImage) || isSubmitting || isUploading}
      className="w-full bg-phase-interactive h-12 rounded-2xl active:opacity-90"
    >
      <ButtonText className="text-inverted font-bold">
        {isSubmitting ? 'Posting...' : submitLabel}
      </ButtonText>
    </Button>
  );

  return (
    <SanctuaryModal isOpen={isOpen} onClose={onClose} title={title} footer={footer}>
      <VStack className="gap-4">
        <Textarea className="bg-phase-surface border-border min-h-[160px] rounded-2xl">
          <TextareaInput
            placeholder={isPollMode ? 'Ask your question...' : placeholder}
            className="text-ink text-base"
            value={content}
            onChangeText={onContentChange}
          />
        </Textarea>

        {isPollMode && (
          <VStack className="gap-4">
            <VStack className="gap-2">
              {pollOptions.map((opt, idx) => {
                return (
                  // biome-ignore lint/suspicious/noArrayIndexKey: indices are stable for poll options within this composer session
                  <HStack key={`poll-option-${idx}`} className="items-center gap-2">
                    <Input className="flex-1 bg-phase-surface border-border h-12 rounded-xl">
                      <InputField
                        placeholder={`Option ${idx + 1}`}
                        value={opt}
                        onChangeText={(val: string) => onUpdatePollOption(idx, val)}
                        className="text-ink text-sm"
                      />
                    </Input>
                    {pollOptions.length > 2 && (
                      <Pressable onPress={() => onRemovePollOption(idx)} className="p-2">
                        <Icon as={X} size="sm" className="text-ink/40" />
                      </Pressable>
                    )}
                  </HStack>
                );
              })}
              {pollOptions.length < 5 && (
                <Pressable onPress={onAddPollOption} className="flex-row items-center py-2 gap-2">
                  <Icon as={Plus} size="xs" className="text-phase-interactive" />
                  <Text className="text-phase-interactive text-sm font-semibold">Add option</Text>
                </Pressable>
              )}
            </VStack>

            <VStack className="gap-3 bg-phase-surface/50 p-4 border border-border rounded-2xl">
              <HStack className="justify-between items-center">
                <HStack className="items-center gap-2">
                  <Icon as={Lock} size="xs" className="text-ink/60" />
                  <Text className="text-ink text-sm">Anonymous votes</Text>
                </HStack>
                <Switch value={pollIsAnonymous} onValueChange={onSetPollAnonymous} />
