                        <Pressable
                          key={p.label || 'none'}
                          onPress={() => {
                            onSetShowCustomDate(false);
                            onSetPollDuration(p.hours);
                          }}
                          className={`px-3 py-1.5 rounded-full border ${isActive ? 'bg-phase-interactive border-phase-interactive' : 'bg-phase-surface border-border'}`}
                        >
