                      className={`px-3 py-1.5 rounded-full border ${active ? 'bg-phase-interactive border-phase-interactive' : 'bg-phase-surface border-border'}`}
                    >
                      <Text
                        className={`text-xs ${active ? 'text-inverted font-semibold' : 'text-ink/60'}`}
