            <Pressable
              onPress={onTogglePollMode}
              className={`p-3 rounded-xl ${isPollMode ? 'bg-phase-interactive' : 'bg-phase-surface'}`}
            >
              <Icon
                as={BarChart3}
                size="md"
                className={isPollMode ? 'text-inverted' : 'text-ink/40'}
              />
            </Pressable>
          )}
        </HStack>
      </VStack>
    </SanctuaryModal>
  );
}

import { useEffect, useRef, useState } from 'react';
import { Platform } from 'react-native';
import { Actionsheet } from '../gluestack';
import { ChevronDown, EyeOff, Lock, Send, Shield, ThumbsUp, Trash2 } from '../icons';
import {
  Box,
  FlatList,
  HStack,
  Icon,
  Input,
  InputField,
  KeyboardAvoidingView,
  Pressable,
  Spinner,
  Text,
  VStack,
} from '../primitives';
import { formatTimestamp, getInitialsFromName } from '../utils';

export interface CommentAuthor {
  id: string;
  name: string;
  avatar?: string | null;
}

export interface CommentItem {
  id: string;
  content: string;
  createdAt: string;
  author: CommentAuthor;
  isAnonymous?: boolean;
  isOfficial?: boolean;
  upvotes: number;
  hasUpvoted?: boolean;
}

interface ConversationSheetProps {
  isOpen: boolean;
  onClose: () => void;
  title?: string;
  comments: CommentItem[];
  isLoading?: boolean;
  isPosting?: boolean;
  currentUserId?: string;

  // Features
  showOfficialBadge?: boolean;
  canMarkOfficial?: boolean;
  canDeleteOwn?: boolean;
  canDeleteAll?: boolean;
  allowAnonymous?: boolean;

  // Handlers
  onPost: (content: string, isAnonymous: boolean) => Promise<void>;
  onDelete: (id: string) => void;
  onUpvote: (id: string) => void;
  onMarkOfficial?: (id: string, flag: boolean) => void;

  // Localization
  emptyTitle?: string;
  emptySubtitle?: string;
  placeholder?: string;
  anonPlaceholder?: string;
}

function CommentRow({
  comment,
  currentUserId,
  showOfficialBadge,
  canMarkOfficial,
  canDelete,
  onDelete,
  onUpvote,
  onMarkOfficial,
}: {
  comment: CommentItem;
  currentUserId?: string;
  showOfficialBadge?: boolean;
  canMarkOfficial?: boolean;
  canDelete?: boolean;
  onDelete: (id: string) => void;
  onUpvote: (id: string) => void;
  onMarkOfficial?: (id: string, flag: boolean) => void;
}) {
  const isOwn = comment.author.id === currentUserId;
  const initials = getInitialsFromName(comment.author.name);

  return (
    <Box
      className={`flex-row mb-5 pl-1 ${comment.isOfficial ? 'border-l-4 border-l-phase-reward' : ''}`}
    >
      <Box
        className={`w-9 h-9 rounded-full items-center justify-center mr-3 mt-1 shrink-0 ${comment.isAnonymous ? 'bg-phase-surface border border-border' : 'bg-phase-interactive/10'}`}
      >
        {comment.isAnonymous ? (
          <Icon as={EyeOff} size="xs" className="text-ink/40" />
        ) : (
          <Text className="text-[12px] font-bold text-phase-interactive">{initials}</Text>
        )}
      </Box>

      <Box className="flex-1">
        <HStack className="justify-between items-center h-5">
          <HStack className="items-center gap-1.5">
            <Text className="text-xs font-bold text-ink">{comment.author.name}</Text>
            {showOfficialBadge && comment.isOfficial && (
              <HStack className="items-center px-1.5 py-0.5 rounded-md bg-phase-reward">
                <Icon as={Shield} size="xs" className="text-white" />
                <Text className="text-[9px] text-white font-bold ml-0.5 uppercase tracking-tighter">
                  Official
                </Text>
              </HStack>
            )}
          </HStack>
          <Text className="text-[10px] text-ink/40">{formatTimestamp(comment.createdAt)}</Text>
        </HStack>

        <Text className="text-sm text-ink/70 mt-1 leading-relaxed">{comment.content}</Text>

        <HStack className="items-center mt-2.5 gap-6">
          <Pressable onPress={() => onUpvote(comment.id)} className="flex-row items-center">
            <Icon
              as={ThumbsUp}
              size="xs"
              className={comment.hasUpvoted ? 'text-phase-interactive' : 'text-ink/40'}
            />
            {comment.upvotes > 0 && (
              <Text
                className={`text-[11px] font-bold ml-1.5 ${comment.hasUpvoted ? 'text-phase-interactive' : 'text-ink/40'}`}
              >
                {comment.upvotes}
              </Text>
            )}
          </Pressable>

          {canMarkOfficial && onMarkOfficial && (
            <Pressable
              onPress={() => onMarkOfficial(comment.id, !comment.isOfficial)}
              className="flex-row items-center"
            >
              <Icon
                as={Shield}
                size="xs"
                className={comment.isOfficial ? 'text-phase-reward' : 'text-ink/40'}
              />
              <Text
                className={`text-[11px] font-bold ml-1.5 ${comment.isOfficial ? 'text-phase-reward' : 'text-ink/40'}`}
              >
                {comment.isOfficial ? 'Unmark' : 'Mark answer'}
              </Text>
            </Pressable>
          )}

          {(isOwn || canDelete) && (
            <Pressable onPress={() => onDelete(comment.id)} className="flex-row items-center p-1">
              <Icon as={Trash2} size="xs" className="text-ink/40" />
            </Pressable>
          )}
        </HStack>
      </Box>
    </Box>
  );
}

export function ConversationSheet({
  isOpen,
  onClose,
  title = 'Conversation',
  comments,
  isLoading,
  isPosting,
  currentUserId,
  showOfficialBadge = true,
  canMarkOfficial = false,
  canDeleteOwn = true,
  canDeleteAll = false,
  allowAnonymous = true,
  onPost,
  onDelete,
  onUpvote,
  onMarkOfficial,
  emptyTitle = 'No reflections yet',
  emptySubtitle = 'Be the first to share your thoughts.',
  placeholder = 'Add a reflection...',
  anonPlaceholder = 'Reflect anonymously...',
}: ConversationSheetProps) {
  const [draft, setDraft] = useState('');
  const [isAnonymous, setIsAnonymous] = useState(false);
  const flatListRef = useRef<FlatList>(null);

  useEffect(() => {
    if (comments.length === 0) return;
    const timer = setTimeout(() => flatListRef.current?.scrollToEnd({ animated: true }), 150);
    return () => clearTimeout(timer);
  }, [comments.length]);

  const handleSend = async () => {
    const trimmed = draft.trim();
    if (!trimmed || isPosting) return;
    setDraft('');
    await onPost(trimmed, isAnonymous);
  };

  return (
    <Actionsheet isOpen={isOpen} onClose={onClose}>
      <Box style={{ height: '80%' }} className="w-full bg-phase-surface">
        <KeyboardAvoidingView
          behavior={Platform.OS === 'ios' ? 'padding' : 'height'}
          keyboardVerticalOffset={Platform.OS === 'ios' ? 0 : 24}
          style={{ flex: 1 }}
        >
          <Box className="flex-1 overflow-hidden">
            {/* Header */}
            <HStack className="items-center px-5 py-4 border-b border-border">
              <Pressable
                onPress={onClose}
                className="w-10 h-10 items-center justify-center rounded-full bg-ink/5"
                hitSlop={12}
              >
                <Icon as={ChevronDown} size="md" className="text-ink/60" />
              </Pressable>
              <Text className="text-md font-bold text-ink flex-1 text-center">
                {isLoading ? 'Loading...' : `${comments.length} ${title}`}
              </Text>
              <Box className="w-10" />
            </HStack>

            {/* Content */}
            {isLoading ? (
              <Box className="flex-1 items-center justify-center">
                <Spinner />
              </Box>
            ) : comments.length === 0 ? (
              <VStack className="flex-1 items-center justify-center py-12 px-8 gap-3">
                <Text className="text-md font-bold text-ink/20">{emptyTitle}</Text>
                <Text className="text-sm text-ink/40 text-center leading-relaxed">
                  {emptySubtitle}
                </Text>
              </VStack>
            ) : (
              <FlatList
                ref={flatListRef}
                data={comments}
                keyExtractor={(item: CommentItem) => item.id}
                contentContainerStyle={{
                  paddingHorizontal: 20,
                  paddingTop: 10,
                  paddingBottom: 24,
                }}
                renderItem={({ item }: { item: CommentItem }) => (
                  <CommentRow
                    comment={item}
                    currentUserId={currentUserId}
                    showOfficialBadge={showOfficialBadge}
                    canMarkOfficial={canMarkOfficial}
                    canDelete={canDeleteAll}
                    onDelete={onDelete}
                    onUpvote={onUpvote}
                    onMarkOfficial={onMarkOfficial}
                  />
                )}
              />
            )}

            {/* Composer */}
            <HStack className="items-end p-4 gap-3 border-t border-border bg-phase-surface/80">
              {allowAnonymous && (
                <Pressable
                  onPress={() => setIsAnonymous((v) => !v)}
                  className={`w-11 h-11 rounded-2xl border items-center justify-center shrink-0 ${isAnonymous ? 'bg-phase-interactive border-phase-interactive' : 'bg-phase-surface border-border'}`}
                  hitSlop={8}
                >
                  <Icon
                    as={Lock}
                    size="sm"
                    className={isAnonymous ? 'text-white' : 'text-ink/40'}
                  />
                </Pressable>
              )}

              <Input className="flex-1 bg-ink/5 rounded-2xl border border-border">
                <InputField
                  className="text-ink text-sm py-2.5 px-3 min-h-[44px] max-h-[120px]"
                  placeholder={isAnonymous ? anonPlaceholder : placeholder}
                  placeholderTextColor="#94a3b8"
                  value={draft}
                  onChangeText={setDraft}
                  multiline
                />
              </Input>

              <Pressable
                onPress={handleSend}
                disabled={!draft.trim() || isPosting}
                className={`w-11 h-11 rounded-2xl items-center justify-center shrink-0 ${!draft.trim() ? 'bg-ink/5' : 'bg-phase-interactive'}`}
              >
                {isPosting ? (
                  <Spinner />
                ) : (
                  <Icon
                    as={Send}
                    size="sm"
                    className={!draft.trim() ? 'text-ink/20' : 'text-white'}
                  />
                )}
              </Pressable>
            </HStack>
          </Box>
        </KeyboardAvoidingView>
      </Box>
    </Actionsheet>
  );
}

import { accountPin, type DeviceAccountRecord, useDeviceAccounts, useStore } from '@repo/core/logic';
import { AlertTriangle, Shield } from 'lucide-react-native';
import { useEffect, useReducer } from 'react';
import { Alert, Platform } from 'react-native';
import { Box, Button, ButtonText, Heading, HStack, Text, VStack } from '../gluestack';
import { useSanctuaryToast } from '../providers/ToastProvider';
import { hapticError, hapticLight, hapticSuccess } from '../utils/haptics';
import AccountPinModal, {
  type AccountPinModalMode,
  type AccountPinModalSubmit,
} from './AccountPinModal';
import SanctuaryModal from './SanctuaryModal';

type PendingPinAction = {
  mode: AccountPinModalMode;
  account: DeviceAccountRecord;
} | null;

type OfflineConfirmAction =
  | { type: 'signOutCurrent' }
  | { type: 'signOutAll' }
  | { type: 'removeAccount'; account: DeviceAccountRecord }
  | null;

type State = {
  pinProtectedIds: Record<string, boolean>;
  pinAction: PendingPinAction;
  pinBusy: boolean;
  offlineConfirm: OfflineConfirmAction;
};

type Action =
  | { type: 'setPinProtectedIds'; value: Record<string, boolean> }
  | { type: 'setPinAction'; value: PendingPinAction }
  | { type: 'setPinBusy'; value: boolean }
  | { type: 'setOfflineConfirm'; value: OfflineConfirmAction };

const initialState: State = {
  pinProtectedIds: {},
  pinAction: null,
  pinBusy: false,
  offlineConfirm: null,
};

function reducer(state: State, action: Action): State {
  switch (action.type) {
    case 'setPinProtectedIds':
      return { ...state, pinProtectedIds: action.value };
    case 'setPinAction':
      return { ...state, pinAction: action.value };
    case 'setPinBusy':
      return { ...state, pinBusy: action.value };
    case 'setOfflineConfirm':
      return { ...state, offlineConfirm: action.value };
    default:
      return state;
  }
}

function getInitials(name: string | null | undefined, email: string | null | undefined) {
  const source = name || email || 'A';
  return (
    source
      .split(/\s+/)
      .filter(Boolean)
      .slice(0, 2)
      .map((part) => part[0]?.toUpperCase() ?? '')
      .join('') || 'A'
  );
}

export default function DeviceAccountManager({
  title = 'Accounts remembered on this device',
  subtitle = 'These can belong to completely different people. Switch carefully, protect them with a PIN, and remove or sign out locally when needed.',
  compact = false,
}: {
  title?: string;
  subtitle?: string;
  compact?: boolean;
}) {
  const isOnline = useStore((state) => state.isOnline);
  const {
    accounts,
    activeAccountId,
    busyAccountId,
    loading,
    switchAccount,
    removeAccount,
    signOutCurrentAccount,
    signOutAllAccounts,
    refresh,
  } = useDeviceAccounts();
  const { showToast } = useSanctuaryToast();
  const [state, dispatch] = useReducer(reducer, initialState);
  const { pinProtectedIds, pinAction, pinBusy, offlineConfirm } = state;

  useEffect(() => {
    let cancelled = false;

    (async () => {
      const entries = await Promise.all(
        accounts.map(
          async (account) =>
            [account.accountId, await accountPin.hasPin(account.accountId)] as const,
        ),
      );

      if (cancelled) return;
      dispatch({
        type: 'setPinProtectedIds',
        value: Object.fromEntries(entries),
      });
    })();

    return () => {
      cancelled = true;
    };
  }, [accounts]);

  const accountLabel = (account: DeviceAccountRecord) =>
    account.fullName || account.email || 'This account';

  const setPinBusy = (value: boolean) => dispatch({ type: 'setPinBusy', value });

  const askForPin = (mode: AccountPinModalMode, account: DeviceAccountRecord) => {
    hapticLight();
    dispatch({ type: 'setPinAction', value: { mode, account } });
  };

  const openOfflineConfirm = (value: OfflineConfirmAction) => {
    hapticLight();
    dispatch({ type: 'setOfflineConfirm', value });
  };

  const closeOfflineConfirm = () => {
    dispatch({ type: 'setOfflineConfirm', value: null });
  };

  const handleSignOutCurrent = async () => {
    if (!isOnline) {
      openOfflineConfirm({ type: 'signOutCurrent' });
      return;
    }

    setPinBusy(true);
    try {
      await signOutCurrentAccount();
      hapticSuccess();
      showToast?.({
        message: 'Signed out the current account from this device',
        type: 'success',
      });
    } catch (error) {
      const message = error instanceof Error ? error.message : 'Could not sign out current account';
      hapticError();
      showToast?.({
        message,
        type: 'error',
      });
    } finally {
      setPinBusy(false);
      refresh();
    }
  };

  const performSignOutAll = async () => {
    setPinBusy(true);
    try {
      await signOutAllAccounts();
      hapticSuccess();
      showToast?.({
        message: 'Signed out all remembered accounts from this device',
        type: 'success',
      });
    } catch (error) {
      const message = error instanceof Error ? error.message : 'Could not sign out all accounts';
      hapticError();
      showToast?.({
        message,
        type: 'error',
      });
    } finally {
      setPinBusy(false);
      refresh();
    }
  };

  const handleSignOutAll = async () => {
    if (!isOnline) {
      openOfflineConfirm({ type: 'signOutAll' });
      return;
    }

    if (Platform.OS === 'web') {
      const confirmed = window.confirm(
        'Sign out every remembered account from this device? This affects only this device install.',
      );
      if (!confirmed) return;
      await performSignOutAll();
      return;
    }

    Alert.alert(
      'Sign out all accounts',
      'Sign out every remembered account from this device? This affects only this device install.',
      [
        { text: 'Cancel', style: 'cancel' },
        {
          text: 'Sign out all',
          style: 'destructive',
          onPress: () => {
            void performSignOutAll();
          },
        },
      ],
    );
  };

  const handleSwitch = async (account: DeviceAccountRecord) => {
    if (pinProtectedIds[account.accountId]) {
      askForPin('verify', account);
      return;
    }

    setPinBusy(true);
    try {
      await switchAccount(account.accountId);
      hapticSuccess();
      showToast?.({
        message: `Switched to ${accountLabel(account)}`,
        type: 'success',
      });
    } catch (error) {
      hapticError();
      showToast?.({
        message: error instanceof Error ? error.message : 'Could not switch account',
        type: 'error',
      });
    } finally {
      setPinBusy(false);
    }
  };

  const performRemoveAccount = async (account: DeviceAccountRecord) => {
    setPinBusy(true);
    try {
      await removeAccount(account.accountId);
      hapticSuccess();
      showToast?.({
        message: `Removed ${accountLabel(account)} from this device`,
        type: 'success',
      });
      refresh();
    } catch (error) {
      hapticError();
      showToast?.({
        message: error instanceof Error ? error.message : 'Could not remove account',
        type: 'error',
      });
    } finally {
      setPinBusy(false);
    }
  };

  const handleRemove = async (account: DeviceAccountRecord) => {
    if (pinProtectedIds[account.accountId]) {
      askForPin('remove', account);
      return;
    }

    if (!isOnline) {
      openOfflineConfirm({ type: 'removeAccount', account });
      return;
    }

    if (Platform.OS === 'web') {
      const confirmed = window.confirm(`Remove ${accountLabel(account)} from this device?`);
      if (!confirmed) return;
      await performRemoveAccount(account);
      return;
    }

    Alert.alert('Remove account', `Remove ${accountLabel(account)} from this device?`, [
      { text: 'Cancel', style: 'cancel' },
      {
        text: 'Remove',
        style: 'destructive',
        onPress: () => {
          void performRemoveAccount(account);
        },
      },
    ]);
  };

  const confirmOfflineAction = async () => {
    if (!offlineConfirm) return;

    setPinBusy(true);
    try {
      if (offlineConfirm.type === 'signOutCurrent') {
        await signOutCurrentAccount();
        hapticSuccess();
        showToast?.({
          message:
            'Signed out this account on the device. You may need internet before signing in again.',
          type: 'success',
        });
      } else if (offlineConfirm.type === 'signOutAll') {
        await signOutAllAccounts();
        hapticSuccess();
        showToast?.({
          message:
            'Signed out all remembered accounts on this device. You may need internet before signing in again.',
          type: 'success',
        });
      } else if (offlineConfirm.type === 'removeAccount') {
        await removeAccount(offlineConfirm.account.accountId);
        hapticSuccess();
        showToast?.({
          message: `Removed ${accountLabel(offlineConfirm.account)} from this device while offline`,
          type: 'success',
        });
      }
    } catch (error) {
      hapticError();
      showToast?.({
        message: error instanceof Error ? error.message : 'Action failed',
        type: 'error',
      });
    } finally {
      setPinBusy(false);
      closeOfflineConfirm();
      refresh();
    }
  };

  const handlePinSubmit = async (values: AccountPinModalSubmit) => {
    if (!pinAction) return;

    const { mode, account } = pinAction;
    setPinBusy(true);
    try {
      if (mode === 'verify') {
        const ok = await accountPin.verifyPin(account.accountId, 'pin' in values ? values.pin : '');
        if (!ok) {
          throw new Error('PIN did not match this account.');
        }
        await switchAccount(account.accountId);
        showToast?.({
          message: `Switched to ${accountLabel(account)}`,
          type: 'success',
        });
        return;
      }

      if (mode === 'create') {
        await accountPin.setPin(account.accountId, 'pin' in values ? values.pin : '');
        dispatch({
          type: 'setPinProtectedIds',
          value: {
            ...pinProtectedIds,
            [account.accountId]: true,
          },
        });
        showToast?.({
          message: `PIN added for ${accountLabel(account)}`,
          type: 'success',
        });
        return;
      }

      if (mode === 'update') {
        const ok = await accountPin.verifyPin(
          account.accountId,
          'currentPin' in values ? values.currentPin : '',
        );
        if (!ok) {
          throw new Error('Current PIN did not match this account.');
        }
        await accountPin.setPin(account.accountId, 'nextPin' in values ? values.nextPin : '');
        dispatch({
          type: 'setPinProtectedIds',
          value: {
            ...pinProtectedIds,
            [account.accountId]: true,
          },
        });
        showToast?.({
          message: `PIN updated for ${accountLabel(account)}`,
          type: 'success',
        });
        return;
      }

      if (mode === 'remove') {
        const ok = await accountPin.verifyPin(account.accountId, 'pin' in values ? values.pin : '');
        if (!ok) {
          throw new Error('PIN did not match this account.');
        }
        await accountPin.removePin(account.accountId);
        dispatch({
          type: 'setPinProtectedIds',
          value: {
            ...pinProtectedIds,
            [account.accountId]: false,
          },
        });
        await removeAccount(account.accountId);
        showToast?.({
          message: `Removed ${accountLabel(account)} from this device`,
          type: 'success',
        });
        return;
      }
    } catch (error) {
      hapticError();
      showToast?.({
        message: error instanceof Error ? error.message : 'Action failed',
        type: 'error',
      });
    } finally {
      setPinBusy(false);
      dispatch({ type: 'setPinAction', value: null });
      refresh();
    }
  };

  const offlineTitle =
    offlineConfirm?.type === 'signOutAll'
      ? 'Sign out all while offline?'
      : offlineConfirm?.type === 'removeAccount'
        ? 'Remove account while offline?'
        : 'Sign out while offline?';

  const offlineBody =
    offlineConfirm?.type === 'signOutAll'
      ? 'This will remove all remembered accounts from this device immediately. Because there is no internet connection, you may not be able to sign back in until connectivity returns.'
      : offlineConfirm?.type === 'removeAccount'
