import type React from 'react';
import { useMemo } from 'react';
import { StyleSheet } from 'react-native';
import { View } from '../primitives';
import Svg, { Circle, G, Line, Polygon, Text as SvgText } from 'react-native-svg';
import { Theme } from '../theme/Theme';

export interface RadarDimension {
  key: string;
  label: string;
  value: number; // 0-100
}

interface InteractiveRadarChartProps {
  dimensions: RadarDimension[];
  size?: number;
  editable?: boolean;
  onChange?: (key: string, newValue: number) => void;
}

/**
 * A beautiful, interactive Radar Chart for student analysis.
 * Uses the Sanctuary Saffron aesthetic with glassmorphic touches.
 */
export const InteractiveRadarChart: React.FC<InteractiveRadarChartProps> = ({
  dimensions,
  size = 300,
  editable = false,
}) => {
  const centerX = size / 2;
  const centerY = size / 2;
  const radius = (size / 2) * 0.7; // Leave space for labels
  const angleStep = (Math.PI * 2) / dimensions.length;

  // Calculate vertex positions for the background polygon (max values)
  const bgPoints = useMemo(() => {
    return dimensions.map((_, i) => {
      const angle = i * angleStep - Math.PI / 2;
      return {
        x: centerX + Math.cos(angle) * radius,
        y: centerY + Math.sin(angle) * radius,
      };
    });
  }, [centerX, centerY, radius, angleStep, dimensions.map]);

  // Calculate vertex positions for the data polygon
  const dataPoints = useMemo(() => {
    return dimensions.map((d, i) => {
      const angle = i * angleStep - Math.PI / 2;
      const distance = (d.value / 100) * radius;
      return {
        x: centerX + Math.cos(angle) * distance,
        y: centerY + Math.sin(angle) * distance,
      };
    });
  }, [dimensions, centerX, centerY, radius, angleStep]);

  const polygonPointsString = dataPoints.map((p) => `${p.x},${p.y}`).join(' ');
  const bgPolygonPointsString = bgPoints.map((p) => `${p.x},${p.y}`).join(' ');

  return (
    <View style={[styles.container, { width: size, height: size }]}>
      <Svg width={size} height={size}>
        {/* Background Grid - Circular Levels */}
        {[20, 40, 60, 80, 100].map((level) => (
          <Polygon
            key={`level-${level}`}
            points={bgPoints
              .map((p) => {
                const dist = level / 100;
                const x = centerX + (p.x - centerX) * dist;
                const y = centerY + (p.y - centerY) * dist;
                return `${x},${y}`;
              })
              .join(' ')}
            fill="none"
            stroke={Theme.colors.border}
            strokeWidth="0.5"
            strokeDasharray="2,2"
          />
        ))}

        {/* Axis Lines */}
        {bgPoints.map((p, i) => (
          <Line
            key={`axis-${i}`}
            x1={centerX}
            y1={centerY}
            x2={p.x}
            y2={p.y}
            stroke={Theme.colors.border}
            strokeWidth="1"
            opacity={0.3}
          />
        ))}

        {/* Background Full Polygon */}
        <Polygon points={bgPolygonPointsString} fill={Theme.colors.linen} opacity={0.1} />

        {/* Data Polygon */}
        <Polygon
          points={polygonPointsString}
          fill={Theme.colors.sanctuarySaffron}
          fillOpacity={0.3}
          stroke={Theme.colors.sanctuarySaffron}
          strokeWidth="2"
        />

        {/* Vertices and Labels */}
        {dataPoints.map((p, i) => {
          const dim = dimensions[i];
          if (!dim) return null;

          // Label positioning
          const labelDist = radius + 20;
          const angle = i * angleStep - Math.PI / 2;
          const labelX = centerX + Math.cos(angle) * labelDist;
          const labelY = centerY + Math.sin(angle) * labelDist;

          return (
            <G key={`vertex-group-${i}`}>
              {/* Label */}
              <SvgText
                x={labelX}
                y={labelY}
                fill={Theme.colors.textSecondary}
                fontSize="10"
                fontWeight="600"
                textAnchor="middle"
                alignmentBaseline="middle"
              >
                {dim.label}
              </SvgText>

              {/* Interaction point */}
              <Circle
                cx={p.x}
                cy={p.y}
                r={editable ? 6 : 4}
                fill={Theme.colors.sanctuarySaffron}
                stroke="white"
                strokeWidth="1"
              />
            </G>
          );
        })}
      </Svg>

      {/* Glow Effect Overlay (subtle) */}
      <View
        style={[styles.glow, { width: size * 0.6, height: size * 0.6, borderRadius: size * 0.3 }]}
        pointerEvents="none"
      />
    </View>
  );
};

const styles = StyleSheet.create({
  container: {
    alignItems: 'center',
    justifyContent: 'center',
    backgroundColor: 'rgba(255, 255, 255, 0.03)',
    borderRadius: 20,
    overflow: 'visible',
  },
  glow: {
    position: 'absolute',
    backgroundColor: Theme.colors.sanctuarySaffron,
    opacity: 0.05,
    zIndex: -1,
  },
});

import * as WebBrowser from 'expo-web-browser';
import { ChevronLeft, ChevronRight, ExternalLink, RotateCcw, Share2, X } from 'lucide-react-native';
import type React from 'react';
import { useCallback, useReducer, useRef } from 'react';
import { Linking, Share, StyleSheet } from 'react-native';
import { ActivityIndicator } from '../primitives';
import { WebView, type WebViewNavigation } from 'react-native-webview';
import { Pressable, Text, useTheme, View } from '../primitives';

export interface InternalBrowserProps {
  url: string;
  onClose?: () => void;
  title?: string;
  showToolbar?: boolean;
}


// ============================================================================
// TYPES & REDUCER
// ============================================================================

interface BrowserState {
  canGoBack: boolean;
  canGoForward: boolean;
  currentUrl: string;
  isLoading: boolean;
  progress: number;
}

type BrowserAction =
  | { type: 'UPDATE_NAVIGATION'; navState: WebViewNavigation }
  | { type: 'SET_PROGRESS'; progress: number }
  | { type: 'SET_LOADING'; loading: boolean }
  | { type: 'SET_URL'; url: string };

function browserReducer(state: BrowserState, action: BrowserAction): BrowserState {
  switch (action.type) {
    case 'UPDATE_NAVIGATION':
      return {
        ...state,
        canGoBack: action.navState.canGoBack,
        canGoForward: action.navState.canGoForward,
        currentUrl: action.navState.url,
        isLoading: action.navState.loading,
      };
    case 'SET_PROGRESS':
      return { ...state, progress: action.progress };
    case 'SET_LOADING':
      return { ...state, isLoading: action.loading };
    case 'SET_URL':
      return { ...state, currentUrl: action.url };
    default:
      return state;
  }
}

// ============================================================================
// MAIN COMPONENT
// ============================================================================

export const InternalBrowser: React.FC<InternalBrowserProps> = ({
  url,
  onClose,
  title,
  showToolbar = true,
}) => {
  const { scene } = useTheme();
  const webViewRef = useRef<WebView>(null);

  const [state, dispatch] = useReducer(browserReducer, {
    canGoBack: false,
    canGoForward: false,
    currentUrl: url,
    isLoading: true,
    progress: 0,
  });

  const { canGoBack, canGoForward, currentUrl, isLoading, progress } = state;

  const handleNavigationStateChange = useCallback((navState: WebViewNavigation) => {
    dispatch({ type: 'UPDATE_NAVIGATION', navState });
  }, []);

  const handleProgress = useCallback((p: number) => {
    dispatch({ type: 'SET_PROGRESS', progress: p });
  }, []);

  const handleLoading = useCallback((loading: boolean) => {
    dispatch({ type: 'SET_LOADING', loading });
  }, []);

  const handleBack = useCallback(() => webViewRef.current?.goBack(), []);
  const handleForward = useCallback(() => webViewRef.current?.goForward(), []);
  const handleReload = useCallback(() => webViewRef.current?.reload(), []);

  const handleShare = useCallback(async () => {
    try {
      await Share.share({
        url: currentUrl,
        message: currentUrl,
      });
    } catch (error) {
      console.error('Error sharing:', error);
    }
  }, [currentUrl]);

  const handleOpenExternal = useCallback(async () => {
    try {
      await WebBrowser.openBrowserAsync(currentUrl);
    } catch (_error) {
      // Fallback to basic Linking
      Linking.openURL(currentUrl);
    }
  }, [currentUrl]);


  return (
    <View style={[styles.container, { backgroundColor: scene.canvas.bg }]}>
      {/* Header / App Bar */}
      <View
        style={[
          styles.header,
          {
            backgroundColor: scene.surface.bg,
            borderBottomColor: scene.surface.border,
            borderBottomWidth: 1,
          },
        ]}
      >
        <View style={styles.headerLeft}>
          {onClose && (
            <Pressable onPress={onClose} style={styles.iconButton}>
              <X size={20} color={scene.text.primary} />
            </Pressable>
          )}
          <View style={styles.titleContainer}>
            <Text numberOfLines={1} style={[styles.title, { color: scene.text.primary }]}>
              {title || 'Internal Browser'}
            </Text>
            <Text numberOfLines={1} style={[styles.url, { color: scene.text.secondary }]}>
              {new URL(currentUrl).hostname}
            </Text>
          </View>
        </View>

        <View style={styles.headerRight}>
          <Pressable onPress={handleOpenExternal} style={styles.iconButton}>
            <ExternalLink size={18} color={scene.text.primary} />
          </Pressable>
        </View>
      </View>

      {/* Progress Bar */}
      {isLoading && progress > 0 && progress < 1 && (
        <View style={[styles.progressBarContainer, { backgroundColor: scene.canvas.border }]}>
          <View
            style={[
              styles.progressBar,
              {
                backgroundColor: scene.primary.main,
                width: `${progress * 100}%`,
              },
            ]}
          />
        </View>
      )}

      {/* WebView */}
      <WebView
        ref={webViewRef}
        source={{ uri: url }}
        onNavigationStateChange={handleNavigationStateChange}
        onLoadProgress={({ nativeEvent }) => handleProgress(nativeEvent.progress)}
        onLoadStart={() => handleLoading(true)}
        onLoadEnd={() => handleLoading(false)}
        style={[styles.webView, { backgroundColor: scene.canvas.bg }]}
        // Security Settings
        javaScriptEnabled={true}
        domStorageEnabled={true}
        allowFileAccess={false}
        allowUniversalAccessFromFileURLs={false}
        originWhitelist={['https://*', 'http://*']}
        incognito={true} // Maintain sandboxing
        // Gurudevi Logic: Display surface only, no JS bridge by default
      />

      {/* Bottom Toolbar */}
      {showToolbar && (
        <View
          style={[
            styles.toolbar,
            {
              backgroundColor: scene.surface.bg,
              borderTopColor: scene.surface.border,
              borderTopWidth: 1,
              paddingBottom: 24, // Extra padding for home indicator
            },
          ]}
        >
          <Pressable
            onPress={handleBack}
            disabled={!canGoBack}
            style={[styles.toolbarButton, !canGoBack && styles.disabled]}
          >
            <ChevronLeft size={24} color={canGoBack ? scene.text.primary : scene.text.muted} />
          </Pressable>

          <Pressable
            onPress={handleForward}
            disabled={!canGoForward}
            style={[styles.toolbarButton, !canGoForward && styles.disabled]}
          >
            <ChevronRight size={24} color={canGoForward ? scene.text.primary : scene.text.muted} />
          </Pressable>

          <View style={{ flex: 1 }} />

          <Pressable onPress={handleReload} style={styles.toolbarButton}>
            <RotateCcw size={20} color={scene.text.primary} />
          </Pressable>

          <Pressable onPress={handleShare} style={styles.toolbarButton}>
            <Share2 size={20} color={scene.text.primary} />
          </Pressable>
        </View>
      )}

      {/* Initial Loading Overlay */}
      {isLoading && progress === 0 && (
        <View style={[styles.loadingOverlay, { backgroundColor: scene.canvas.bg }]}>
          <ActivityIndicator color={scene.primary.main} />
        </View>
      )}
    </View>
  );
};

