import { AlertCircle, ChevronDown } from 'lucide-react-native';
import { useState } from 'react';
import { Pressable } from '../primitives';
import {
  Actionsheet,
  ActionsheetContent,
  ActionsheetDragIndicator,
  ActionsheetDragIndicatorWrapper,
  ActionsheetItem,
  ActionsheetItemText,
  HStack,
  Text,
  VStack,
} from '../gluestack';

interface LotusDropdownProps {
  label?: string;
  value: string;
  options: Array<{ label: string; value: string }>;
  onChange: (value: string) => void;
  error?: string;
  placeholder?: string;
  isDisabled?: boolean;
}

/**
 * LotusDropdown
 *
 * A hardened, phase-aware dropdown component.
 * Uses Actionsheet for a premium mobile experience.
 */
export default function LotusDropdown({
  label,
  value,
  options,
  onChange,
  error,
  placeholder = 'Select an option',
  isDisabled = false,
}: LotusDropdownProps) {
  const [showActionsheet, setShowActionsheet] = useState(false);

  const selectedOption = options.find((opt) => opt.value === value);
  const hasError = !!error;

  const handleClose = () => setShowActionsheet(false);

  return (
    <VStack className="w-full gap-2">
      {label && <Text className="text-phase-text-primary font-medium tracking-wide">{label}</Text>}

      <Pressable
        onPress={() => !isDisabled && setShowActionsheet(true)}
        className={`
                    flex-row items-center justify-between h-12 px-4 rounded-xl border
                    ${isDisabled ? 'opacity-50' : 'active:opacity-70'}
                    ${hasError ? 'border-phase-danger bg-phase-danger/5' : 'border-phase-surface bg-phase-surface'}
                `}
      >
        <Text
          className={`text-base ${selectedOption ? 'text-phase-text-primary' : 'text-phase-text-secondary'}`}
        >
          {selectedOption ? selectedOption.label : placeholder}
        </Text>
        <ChevronDown size={20} className="text-phase-text-secondary" />
      </Pressable>

      {hasError && (
        <HStack className="items-center gap-1.5 px-1">
          <AlertCircle size={14} className="text-phase-danger" />
          <Text className="text-phase-danger text-xs font-medium">{error}</Text>
        </HStack>
      )}

      <Actionsheet isOpen={showActionsheet} onClose={handleClose}>
        <ActionsheetContent className="bg-phase-elevated border-t border-phase-surface pb-8">
          <ActionsheetDragIndicatorWrapper>
            <ActionsheetDragIndicator />
          </ActionsheetDragIndicatorWrapper>

          <VStack className="w-full p-2">
            {options.map((option) => (
              <ActionsheetItem
                key={option.value}
                onPress={() => {
                  onChange(option.value);
                  handleClose();
                }}
                className={`rounded-xl mb-1 ${value === option.value ? 'bg-phase-accent/10 border border-phase-accent/20' : 'active:bg-phase-surface'}`}
              >
                <ActionsheetItemText
                  className={`text-base ${value === option.value ? 'text-phase-accent font-bold' : 'text-phase-text-primary'}`}
                >
                  {option.label}
                </ActionsheetItemText>
              </ActionsheetItem>
            ))}
          </VStack>
        </ActionsheetContent>
      </Actionsheet>
    </VStack>
  );
}

import { Flower } from 'lucide-react-native';
import { useEffect } from 'react';
import { ActivityIndicator } from '../primitives';
import Animated, {
  Easing,
  useAnimatedStyle,
  useSharedValue,
  withRepeat,
  withSequence,
  withTiming,
} from 'react-native-reanimated';
import { Center, Text, VStack } from '../gluestack';

interface LotusLoaderProps {
  size?: 'sm' | 'md' | 'lg';
  text?: string;
  fullscreen?: boolean;
}

const SIZES = {
  sm: 24,
  md: 48,
  lg: 72,
};

export default function LotusLoader({
  size = 'md',
  text = 'Loading...',
  fullscreen = false,
}: LotusLoaderProps) {
  const scale = useSharedValue(1);
  const opacity = useSharedValue(0.6);
  const rotation = useSharedValue(0);

  useEffect(() => {
    // Breathing animation
    scale.value = withRepeat(
      withSequence(
        withTiming(1.2, { duration: 1500, easing: Easing.inOut(Easing.ease) }),
        withTiming(1.0, { duration: 1500, easing: Easing.inOut(Easing.ease) }),
      ),
      -1,
      true,
    );

    // Glow pulse
    opacity.value = withRepeat(
      withSequence(withTiming(1, { duration: 1500 }), withTiming(0.6, { duration: 1500 })),
      -1,
      true,
    );

    // Gentle rotation
    rotation.value = withRepeat(
      withTiming(360, { duration: 12000, easing: Easing.linear }),
      -1,
      false,
    );
  }, [
    // Breathing animation
    scale, // Gentle rotation
    rotation, // Glow pulse
    opacity,
  ]);

  const animatedStyle = useAnimatedStyle(() => ({
    transform: [{ scale: scale.value }, { rotate: `${rotation.value}deg` }] as any,
    opacity: opacity.value,
  }));

  const content = (
    <VStack space="md" className="items-center justify-center">
      <Animated.View style={animatedStyle}>
        <Flower size={SIZES[size]} className="text-phase-accent" strokeWidth={1.5} />
      </Animated.View>
      <ActivityIndicator size="large" className="text-phase-text-secondary" />
      {text && <Text className="text-phase-text-secondary text-sm tracking-[1px]">{text}</Text>}
    </VStack>
  );

  if (fullscreen) {
    return (
      <Center className="flex-1 z-[1000] bg-phase-canvas absolute top-0 left-0 right-0 bottom-0">
        {content}
      </Center>
    );
  }

  return <Center className="p-8">{content}</Center>;
}

