import { Wind } from 'lucide-react-native';
import type React from 'react';
import { type FC, useCallback, useEffect, useMemo, useRef, useState, memo } from 'react';
import Animated, {
  Easing,
  type SharedValue,
  useAnimatedStyle,
  useSharedValue,
  withRepeat,
  withSequence,
  withSpring,
  withTiming,
} from 'react-native-reanimated';
import { Dimensions, PanResponder, Platform } from '../primitives';
import { useFAB } from '../context/FABContext';
import { Box, HStack, Pressable, Text, VStack } from '../gluestack';
import { useAccessibility } from '../hooks/useAccessibility';
import { hapticLight } from '../utils/haptics';
import { useBottomTabPadding } from './ScreenWrapper';
import { UniversalModal } from './UniversalModal';

// ============================================================================
// TYPES
// ============================================================================

import type { ActionItem, TabType } from '../types/fab';

interface LotusPetalFABProps {
  currentTab?: TabType;
  onPress?: () => void;
  icon?: React.ReactNode;
  actions?: ActionItem[];
  scrollY?: SharedValue<number>;
  disabled?: boolean;
  bottomInset?: number;
  hasActiveGaps?: boolean;
  gapPriority?: 'low' | 'medium' | 'high';
  onBreathingReset?: () => void;
  useGlobal?: boolean;
  className?: string;
}

// ============================================================================
// CONSTANTS
// ============================================================================

const FAB_SIZE = 56;
const FAB_EDGE_MARGIN = 24; // Equivalent to Theme.spacing.lg
const FAB_DRAG_THRESHOLD = 8;
const FAB_WEB_STORAGE_KEY = 'gurudevi_lotus_fab_position_v1';

const fabConfig: Record<TabType, { emoji: string; label: string }> = {
  self: { emoji: '≡ƒ¬╖', label: 'Reflection' },
  classroom: { emoji: 'Γ₧ò', label: 'Add' },
  community: { emoji: '≡ƒÆ¼', label: 'Community' },
  library: { emoji: '≡ƒôÜ', label: 'Library' },
  profile: { emoji: '≡ƒæñ', label: 'Profile' },
  section: { emoji: '≡ƒÅó', label: 'Section' },
  grade: { emoji: '≡ƒÅ½', label: 'Grade' },
  principal: { emoji: '≡ƒææ', label: 'Management' },
  founder: { emoji: '≡ƒÅ¢∩╕Å', label: 'Founder' },
};

// ============================================================================
// ACTION ITEM COMPONENT (FOR MEMOIZATION)
// ============================================================================

const FABActionItem: FC<{ action: ActionItem; onPress: (a: ActionItem) => void }> = ({
  action,
  onPress,
}) => {
  const handlePress = useCallback(() => onPress(action), [action, onPress]);

  return (
    <Pressable
      onPress={handlePress}
      accessible={true}
      accessibilityRole="button"
      accessibilityLabel={action.label}
      className="p-4 rounded-xl hover:bg-white/5 active:bg-white/10"
    >
      <HStack className="items-center gap-3">
        {action.icon && <action.icon size={20} color="#F6BF8C" strokeWidth={2} />}
        <Text className="text-phase-text-primary">{action.label}</Text>
      </HStack>
    </Pressable>
  );
};

// ============================================================================
// MAIN COMPONENT
// ============================================================================

export const LotusPetalFAB: FC<LotusPetalFABProps> = memo(({
  currentTab: propTab,
  onPress: propPress,
  icon: customIcon,
  actions: propActions,
  disabled = false,
  bottomInset = 24,
  hasActiveGaps: propGaps,
  onBreathingReset: propReset,
  useGlobal = true,
  className,
}: LotusPetalFABProps) => {
  const { state: globalState } = useFAB();
  const { isReduceMotionEnabled } = useAccessibility();
  const bottomTabPadding = useBottomTabPadding();

  // Reconcile props with global state
  const currentTab = (propTab || globalState.tabType) as TabType;
  const actions = propActions || globalState.actions;
  const hasActiveGaps = propGaps ?? globalState.hasActiveGaps;
  const onPress = propPress || globalState.onPress;
  const onBreathingReset = propReset || globalState.onBreathingReset;
  const isVisible = useGlobal ? globalState.visible : true;
  const icon = customIcon || globalState.icon;

  const config = useMemo(() => fabConfig[currentTab] || fabConfig.self, [currentTab]);

  // Reanimated Shared Values
  const pressScale = useSharedValue(1);
  const breathingScale = useSharedValue(1);
  const pulseOpacity = useSharedValue(0.4);

  // Position Shared Values for Draggability
  const positionX = useSharedValue(0);
  const positionY = useSharedValue(0);
  const dragStartX = useRef(0);
  const dragStartY = useRef(0);

  const [isDrawerVisible, setIsDrawerVisible] = useState(false);

  const clampFabToViewport = useCallback(
    (x: number, y: number) => {
      const windowDims = Dimensions.get('window');
      const maxX = Math.max(FAB_EDGE_MARGIN, windowDims.width - FAB_SIZE - FAB_EDGE_MARGIN);
      const maxY = Math.max(
        FAB_EDGE_MARGIN,
        windowDims.height - FAB_SIZE - FAB_EDGE_MARGIN - (bottomInset + bottomTabPadding),
      );
      return {
        x: Math.max(FAB_EDGE_MARGIN, Math.min(maxX, x)),
        y: Math.max(FAB_EDGE_MARGIN, Math.min(maxY, y)),
      };
    },
    [bottomInset, bottomTabPadding],
  );

  const persistWebPosition = useCallback((x: number, y: number) => {
    if (Platform.OS !== 'web') return;
    try {
      if (typeof window === 'undefined' || !window.localStorage) return;
      window.localStorage.setItem(FAB_WEB_STORAGE_KEY, JSON.stringify({ x, y }));
    } catch {
      // Ignore storage failures
    }
  }, []);

  const setDefaultPosition = useCallback(() => {
    const windowDims = Dimensions.get('window');
    const preferredX = windowDims.width - FAB_SIZE - FAB_EDGE_MARGIN;
    const preferredY =
      windowDims.height - FAB_SIZE - FAB_EDGE_MARGIN - (bottomInset + bottomTabPadding);
    const next = clampFabToViewport(preferredX, preferredY);
    positionX.value = next.x;
    positionY.value = next.y;
  }, [bottomInset, bottomTabPadding, clampFabToViewport, positionX, positionY]);

  const handlePress = useCallback(() => {
    if (disabled) return;
    hapticLight();

    if (actions && actions.length > 0) {
      setIsDrawerVisible(true);
      return;
    }

    if (onPress) {
      pressScale.value = withSequence(withTiming(0.9, { duration: 100 }), withSpring(1));
      onPress();
    }
  }, [disabled, onPress, actions, pressScale]);

  useEffect(() => {
    let initialized = false;
    if (Platform.OS === 'web') {
      try {
        if (typeof window !== 'undefined' && window.localStorage) {
          const raw = window.localStorage.getItem(FAB_WEB_STORAGE_KEY);
          if (raw) {
            const parsed = JSON.parse(raw);
            if (typeof parsed?.x === 'number' && typeof parsed?.y === 'number') {
              const next = clampFabToViewport(parsed.x, parsed.y);
              positionX.value = next.x;
              positionY.value = next.y;
              initialized = true;
            }
          }
        }
      } catch {
        // Ignore and use default position
      }
    }

    if (!initialized) {
      setDefaultPosition();
    }
  }, [clampFabToViewport, positionX, positionY, setDefaultPosition]);

  useEffect(() => {
    const sub = Dimensions.addEventListener('change', () => {
      const next = clampFabToViewport(positionX.value, positionY.value);
      positionX.value = next.x;
      positionY.value = next.y;
      persistWebPosition(next.x, next.y);
    });
    return () => sub.remove();
  }, [clampFabToViewport, persistWebPosition, positionX, positionY]);

  // PanResponder for draggability
  const panResponder = useRef(
    PanResponder.create({
      onStartShouldSetPanResponder: () => true,
      onMoveShouldSetPanResponder: (_, gesture) => {
        return (
          Math.abs(gesture.dx) > FAB_DRAG_THRESHOLD || Math.abs(gesture.dy) > FAB_DRAG_THRESHOLD
        );
      },
      onPanResponderGrant: () => {
        dragStartX.current = positionX.value;
        dragStartY.current = positionY.value;
        pressScale.value = withSpring(1.1);
        hapticLight();
      },
      onPanResponderMove: (_, gesture) => {
        const next = clampFabToViewport(
          dragStartX.current + gesture.dx,
          dragStartY.current + gesture.dy,
        );
        positionX.value = next.x;
        positionY.value = next.y;
      },
      onPanResponderRelease: (_, gesture) => {
        pressScale.value = withSpring(1);

        // Tap
        if (
          Math.abs(gesture.dx) < FAB_DRAG_THRESHOLD &&
          Math.abs(gesture.dy) < FAB_DRAG_THRESHOLD
        ) {
          handlePress();
          return;
        }

        const next = clampFabToViewport(positionX.value, positionY.value);
        positionX.value = withSpring(next.x, { damping: 15 });
        positionY.value = withSpring(next.y, { damping: 15 });
        persistWebPosition(next.x, next.y);
      },
    }),
  ).current;

  // Breathing Animation
  useEffect(() => {
    if (!disabled && !isReduceMotionEnabled) {
      breathingScale.value = withRepeat(
        withTiming(1.1, { duration: 4000, easing: Easing.inOut(Easing.ease) }),
        -1,
        true,
      );
      pulseOpacity.value = withRepeat(
        withTiming(0.7, { duration: 4000, easing: Easing.inOut(Easing.ease) }),
        -1,
        true,
      );
    }
  }, [disabled, isReduceMotionEnabled, breathingScale, pulseOpacity]);

  const containerStyle = useAnimatedStyle(() => ({
    left: positionX.value,
    top: positionY.value,
    transform: [{ scale: pressScale.value }],
  }));

  const breathingStyle = useAnimatedStyle(() => ({
    transform: [{ scale: breathingScale.value }],
    opacity: pulseOpacity.value,
  }));

  const closeDrawer = useCallback(() => setIsDrawerVisible(false), []);

  const handleBreathingReset = useCallback(() => {
    setIsDrawerVisible(false);
    onBreathingReset?.();
  }, [onBreathingReset]);

  const handleActionPress = useCallback((action: ActionItem) => {
    setIsDrawerVisible(false);
    action.onPress();
  }, []);

  if (!isVisible) return null;

  return (
    <Box className="absolute inset-0 z-[1000] pointer-events-none">
      <Animated.View
        {...panResponder.panHandlers}
        style={[containerStyle]}
        className="absolute w-14 h-14 items-center justify-center pointer-events-auto"
      >
        {/* Breathing Glow */}
        <Animated.View
          style={breathingStyle}
          className={`
                        absolute w-[72px] h-[72px] rounded-full
                        ${hasActiveGaps ? 'bg-phase-error opacity-60' : 'bg-phase-accent opacity-40'}
                    `}
        />

        {/* Main FAB Circle */}
        <Box
          className={`
                        w-14 h-14 rounded-full items-center justify-center bg-phase-accent
                        shadow-xl shadow-black/30 border-2 border-white/10
                        ${className || ''}
                    `}
        >
          {hasActiveGaps ? (
            <Text className="text-2xl">Γ¥ù</Text>
          ) : icon ? (
            icon
          ) : (
            <Text className="text-2xl">{config.emoji}</Text>
          )}
        </Box>
      </Animated.View>

      {/* Action Drawer */}
      <UniversalModal isOpen={isDrawerVisible} onClose={closeDrawer}>
        <Pressable
          accessibilityRole="button"
          className="flex-1 bg-black/50 justify-end"
          onPress={closeDrawer}
        >
          <Box className="bg-phase-surface rounded-t-[32px] p-8 min-h-[40vh] w-full mt-auto">
            <Box className="w-10 h-1 bg-phase-text-secondary/30 rounded-full self-center mb-6" />

            <VStack className="gap-4">
              <Text className="text-xl font-bold text-phase-text-primary mb-2">
                {config.label} Actions
              </Text>

              {onBreathingReset && (
                <Pressable
                  accessibilityRole="button"
                  onPress={handleBreathingReset}
                  className="p-4 rounded-xl bg-phase-success/10 active:bg-phase-success/20"
                >
                  <HStack className="items-center gap-3">
                    <Wind size={20} color="#10B981" strokeWidth={2} />
                    <Text className="text-phase-text-primary font-semibold">Breathing Reset</Text>
                  </HStack>
                </Pressable>
              )}

              {actions?.map((action: ActionItem, idx: number) => (
                <FABActionItem key={idx} action={action} onPress={handleActionPress} />
              ))}
            </VStack>
          </Box>
        </Pressable>
      </UniversalModal>
    </Box>
  );
});

export default LotusPetalFAB;

import { Bell, BookOpen, Check, CheckCircle, Info, Users, X } from 'lucide-react-native';
import { Dimensions } from 'react-native';
import { ScrollView } from '../primitives';
import Animated, { Easing, SlideInLeft, SlideOutLeft } from 'react-native-reanimated';
import { useSafeAreaInsets } from 'react-native-safe-area-context';
import { Box, Heading, HStack, Portal, Pressable, Spinner, Text, VStack } from '../gluestack';
import { hapticLight } from '../utils/haptics';

const { width } = Dimensions.get('window');
const DRAWER_WIDTH = width * 0.65;

interface NotificationDrawerProps {
  isVisible: boolean;
  onClose: () => void;
  notifications?: Array<{
    id: string;
    type: string;
    title: string;
    body: string | null;
    is_read: boolean;
    created_at: string;
  }>;
  unreadCount?: number;
  isLoading?: boolean;
  onMarkRead?: (id: string) => void;
  onMarkAllRead?: () => void;
}

function notificationIcon(type: string) {
  switch (type) {
    case 'new_submission':
      return BookOpen;
    case 'submission_graded':
      return CheckCircle;
    case 'new_post':
      return Users;
    case 'group_joined':
      return Users;
    case 'school_circular':
      return Bell;
    case 'system':
      return Info;
    default:
      return Info;
  }
}

function relativeTime(dateStr: string): string {
  const ts = new Date(dateStr).getTime();
  if (Number.isNaN(ts)) return '';
  const diff = Date.now() - ts;
  const mins = Math.floor(diff / 60000);
  if (mins < 1) return 'just now';
  if (mins < 60) return `${mins}m ago`;
  const hours = Math.floor(mins / 60);
  if (hours < 24) return `${hours}h ago`;
  return `${Math.floor(hours / 24)}d ago`;
}

export default function NotificationDrawer({
  isVisible,
  onClose,
  notifications = [],
  unreadCount = 0,
  isLoading = false,
  onMarkRead,
  onMarkAllRead,
}: NotificationDrawerProps) {
  const insets = useSafeAreaInsets();

  if (!isVisible) return null;

  return (
    <Portal>
      <Box className="flex-1 bg-black/40">
        <Pressable
          accessibilityRole="button"
          className="absolute inset-0"
          onPress={() => {
            hapticLight();
            onClose();
          }}
        />

        <Animated.View
          entering={SlideInLeft.duration(800).easing(Easing.out(Easing.exp))}
          exiting={SlideOutLeft.duration(500)}
          style={{
            position: 'absolute',
            top: 0,
            left: 0,
            bottom: 0,
            width: DRAWER_WIDTH,
            paddingTop: insets.top,
            paddingBottom: insets.bottom,
          }}
          className="bg-phase-canvas border-r border-phase-surface shadow-2xl"
        >
          <VStack className="flex-1 p-6 gap-4">
            {/* Header */}
            <HStack className="justify-between items-center h-[60px]">
              <HStack className="items-center gap-2">
                <Bell size={24} color="#F6BF8C" />
                <Heading size="lg" className="text-phase-text-primary">
                  Notifications
                </Heading>
                {unreadCount > 0 && (
                  <Box className="bg-phase-accent rounded-full min-w-[20px] h-5 items-center justify-center px-1">
                    <Text className="text-white text-[11px] font-bold">
                      {unreadCount > 99 ? '99+' : unreadCount}
                    </Text>
                  </Box>
                )}
              </HStack>
              <HStack className="items-center gap-2">
                {unreadCount > 0 && onMarkAllRead && (
                  <Pressable
                    accessibilityRole="button"
                    onPress={() => {
                      hapticLight();
                      onMarkAllRead();
                    }}
                    hitSlop={10}
                  >
                    <Check size={18} color="#F6BF8C" />
                  </Pressable>
                )}
                <Pressable
                  accessibilityRole="button"
                  onPress={() => {
                    hapticLight();
                    onClose();
                  }}
                  hitSlop={10}
                >
                  <X size={28} className="text-phase-text-secondary" />
                </Pressable>
              </HStack>
            </HStack>

            <ScrollView
              showsVerticalScrollIndicator={false}
              contentContainerStyle={{ paddingBottom: 40 }}
            >
              {isLoading ? (
                <Box className="items-center py-10">
                  <Spinner className="text-phase-accent" />
                </Box>
              ) : notifications.length === 0 ? (
                <VStack className="items-center py-10 gap-2">
                  <Bell size={40} color="#666" style={{ opacity: 0.3 }} />
                  <Text className="text-center text-phase-text-secondary text-sm">
                    You're all caught up Γ£¿
                  </Text>
                </VStack>
              ) : (
                <VStack className="mt-4 gap-2">
                  {notifications.map((n) => {
                    const Icon = notificationIcon(n.type);
                    return (
                      <Pressable
                        accessibilityRole="button"
                        key={n.id}
                        onPress={() => {
                          hapticLight();
                          if (!n.is_read && onMarkRead) onMarkRead(n.id);
                        }}
                      >
                        <Box
                          className={`p-4 rounded-xl border ${
                            n.is_read
                              ? 'bg-phase-surface border-phase-surface'
                              : 'bg-phase-accent/10 border-phase-accent/30'
                          }`}
                        >
                          <HStack className="items-start gap-2">
                            <Box className="p-2 rounded-full bg-phase-surface">
                              <Icon size={16} color={n.is_read ? '#666' : '#F6BF8C'} />
                            </Box>
                            <VStack className="flex-1 gap-1">
                              <Text
                                className={`text-phase-text-primary text-sm ${n.is_read ? 'font-normal' : 'font-bold'}`}
                              >
                                {n.title}
                              </Text>
                              {n.body ? (
                                <Text
                                  className="text-phase-text-secondary text-xs"
                                  numberOfLines={2}
                                >
                                  {n.body}
                                </Text>
                              ) : null}
                              <Text className="text-phase-text-secondary text-[10px]">
                                {relativeTime(n.created_at)}
                              </Text>
                            </VStack>
                          </HStack>
                        </Box>
                      </Pressable>
                    );
                  })}
                </VStack>
              )}
            </ScrollView>

            <Text className="text-phase-text-secondary text-center text-xs italic mb-4">
              Your sanctuary stays updated.
            </Text>
          </VStack>
        </Animated.View>
      </Box>
    </Portal>
  );
}

import React from 'react';
import { Animated } from 'react-native';
import { useTheme } from '../hooks/useTheme';
import { Check, Clock, Lock } from '../icons';
import { AnimatedView, Box, HStack, Icon, Pressable, Spinner, Text, VStack } from '../primitives';
import { Theme } from '../theme/Theme';

export interface PollOption {
  id: string;
  text: string;
}

export interface PollData {
  options: PollOption[];
  allow_multiple?: boolean;
  is_anonymous?: boolean;
  ends_at?: string | null;
}

interface PollWidgetProps {
  postId: string;
  pollData: PollData;
  counts: Record<string, number>;
  userVotes: Set<string>;
  totalVotes: number;
  isLoading?: boolean;
  isVoting?: boolean;
  isAuthor?: boolean;
  onVote: (optionId: string) => void;
  onRefresh?: () => void;
}

export function PollWidget({
  pollData,
  counts,
  userVotes,
  totalVotes,
  isLoading = false,
  isVoting = false,
  isAuthor = false,
  onVote,
  onRefresh,
}: PollWidgetProps) {
  const {
    options = [],
    allow_multiple = false,
    is_anonymous: pollAnon = false,
    ends_at,
  } = pollData;

  const theme = useTheme();
  const [timeLeft, setTimeLeft] = React.useState<string | null>(null);
  const [isExpired, setIsExpired] = React.useState(false);

  const progressAnims = React.useRef<Record<string, Animated.Value>>({});

  // Initialize animated values for options
  React.useEffect(() => {
    options.forEach((opt) => {
      if (!progressAnims.current[opt.id]) {
        progressAnims.current[opt.id] = new Animated.Value(0);
      }
    });
  }, [options]);

  const hasVoted = userVotes.size > 0;
  const showResults = hasVoted || isExpired || isAuthor;
  const maxCount = options.reduce((m, o) => Math.max(m, counts[o.id] ?? 0), 0);

  React.useEffect(() => {
    if (!showResults) return;
    options.forEach((opt) => {
      const pct = totalVotes > 0 ? ((counts[opt.id] ?? 0) / totalVotes) * 100 : 0;
      Animated.timing(progressAnims.current[opt.id]!, {
        toValue: pct,
        duration: 500,
        useNativeDriver: false, // Layout animation
      }).start();
    });
  }, [counts, totalVotes, showResults, options]);

  React.useEffect(() => {
    if (!ends_at) return;
    const tick = () => {
      const diff = new Date(ends_at).getTime() - Date.now();
      if (diff <= 0) {
        setIsExpired(true);
        setTimeLeft(null);
        return;
      }
      const totalMins = Math.floor(diff / 60_000);
      const d = Math.floor(totalMins / (60 * 24));
      const h = Math.floor((totalMins % (60 * 24)) / 60);
      const m = totalMins % 60;
      setTimeLeft(d > 0 ? `${d}d ${h}h left` : h > 0 ? `${h}h ${m}m left` : `${m}m left`);
    };
    tick();
    const timer = setInterval(tick, 30_000);
    return () => clearInterval(timer);
  }, [ends_at]);

  if (isLoading) {
    return <Spinner size="small" className="mt-3" />;
  }

  return (
    <VStack className="gap-2 mt-2">
      <HStack className="justify-between items-center">
        <HStack className="items-center gap-1.5">
          {pollAnon && (
            <Box className="bg-phase-interactive px-2 py-0.5 rounded-md flex-row items-center gap-1">
              <Icon as={Lock} size={11} color={theme.text.secondary} />
              <Text className="text-phaseText-secondary text-[10px]">Anonymous</Text>
            </Box>
          )}
          {allow_multiple && (
            <Box className="bg-phase-interactive px-2 py-0.5 rounded-md">
              <Text className="text-phaseText-secondary text-[10px]">Multi-select</Text>
            </Box>
          )}
        </HStack>

        {isExpired ? (
          <HStack className="items-center gap-1">
            <Icon as={Clock} size={12} color={theme.text.secondary} />
            <Text className="text-phaseText-secondary text-[11px]">Poll ended</Text>
          </HStack>
        ) : timeLeft ? (
          <HStack className="items-center gap-1">
            <Icon as={Clock} size={12} color={theme.accent.action} />
            <Text className="text-phase-accent text-[11px]">{timeLeft}</Text>
          </HStack>
        ) : null}
      </HStack>

      {options.map((opt) => {
        const count = counts[opt.id] ?? 0;
        const isSelected = userVotes.has(opt.id);
        const isWinner = isExpired && count > 0 && count === maxCount;
        const canTap = !isExpired && !isVoting;

        return (
          <Pressable
            key={opt.id}
            onPress={() => onVote(opt.id)}
            disabled={!canTap}
            accessibilityRole="button"
            accessibilityLabel={`Vote for ${opt.text}. Current votes: ${totalVotes > 0 ? Math.round((count / totalVotes) * 100) : 0}%`}
            className={`
              h-12 rounded-xl overflow-hidden relative justify-center border
              ${isWinner ? 'border-sanctuarySaffron' : isSelected ? 'border-phase-accent' : 'border-phase-interactive'}
              ${isSelected ? 'border-2' : 'border-1'}
              bg-phase-surface
            `}
          >
            {showResults && (
              <AnimatedView
                style={{
                  position: 'absolute',
                  left: 0,
                  top: 0,
                  bottom: 0,
                  width: progressAnims.current[opt.id]!.interpolate({
                    inputRange: [0, 100],
                    outputRange: ['0%', '100%'],
                  }),
                  backgroundColor: isWinner
                    ? `${Theme.colors.sanctuarySaffron}20`
                    : isSelected
                      ? `${theme.accent.action}15`
                      : `${theme.scene.interactive.bg}40`,
                }}
              />
            )}
            <HStack className="justify-between px-3 z-1 items-center w-full">
              <HStack className="items-center gap-2 flex-1">
                <Box
                  className={`
                    w-[18px] h-[18px] items-center justify-center border-2
                    ${allow_multiple ? 'rounded-[4px]' : 'rounded-full'}
                    ${isSelected ? 'bg-phase-accent border-phase-accent' : 'border-phase-interactive'}
                  `}
                >
                  {isSelected && <Icon as={Check} size={12} color="white" />}
                </Box>
                <Text
                  className={`text-phaseText-primary text-sm ${isSelected ? 'font-bold' : 'font-normal'}`}
                >
                  {opt.text}
                </Text>
              </HStack>
              {showResults && (
                <Text
                  className={`font-bold text-xs ${isSelected ? 'text-phase-accent' : 'text-phaseText-secondary'}`}
                >
                  {totalVotes > 0 ? Math.round((count / totalVotes) * 100) : 0}%
                </Text>
              )}
            </HStack>
          </Pressable>
        );
      })}

      <HStack className="justify-between mt-1">
        <Text className="text-phaseText-secondary text-[11px]">
          {totalVotes} {totalVotes === 1 ? 'vote' : 'votes'}
        </Text>
        {hasVoted && !isExpired && onRefresh && (
          <Pressable
            onPress={onRefresh}
            accessibilityRole="button"
            accessibilityLabel="Change your vote"
          >
            <Text className="text-phase-accent text-[11px] font-semibold">Change vote</Text>
          </Pressable>
        )}
      </HStack>
    </VStack>
  );
}

import { formatDistanceToNow } from 'date-fns';
import React from 'react';
import { useTheme } from '../hooks/useTheme';
import {
  AlertTriangle,
  BookOpen,
  CheckCircle2,
  FileText,
  Heart,
  Link2,
  MessageCircle,
  MoreHorizontal,
  Music,
  Share2,
  ShieldAlert,
  Sparkles,
  UserX,
  Video,
  X as XIcon,
} from '../icons';
import {
  Avatar,
  AvatarFallbackText,
  AvatarImage,
  Box,
  HStack,
  Icon,
  Image,
  Pressable,
  Text,
  VStack,
} from '../primitives';
import { Theme } from '../theme/Theme';
import { LivingGlow } from './LivingGlow';
import { type PollData, PollWidget } from './PollWidget';
import { SanctuaryCard } from './SanctuaryCard';

export interface Author {
  id: string;
  name: string;
  avatar?: string;
}

export type PostType =
  | 'announcement'
  | 'question'
  | 'resource'
  | 'feedback'
  | 'discussion'
  | 'poll';
export type Urgency = 'low' | 'medium' | 'high';
export type FeedbackStatus = 'pending' | 'under_review' | 'approved' | 'implemented' | 'declined';

export interface PostContent {
  id: string;
  author: Author;
  content: string;
  type: PostType;
  createdAt: string | Date;
  mediaUrl?: string;
  mediaType?: 'image' | 'video' | 'audio' | 'document';
  isAnonymous?: boolean;
  pollData?: PollData;
  urgency?: Urgency;
  hasAcceptedAnswer?: boolean;
  feedbackStatus?: FeedbackStatus;
  feedbackResponse?: string;
  commentCount?: number;
}

interface PostCardProps {
  post: PostContent;
  currentUserId?: string;

  // State from parent logic hook
  isLiked: boolean;
  likeCount: number;
  hasResonated: boolean;
  isResonating: boolean;
  isMenuOpen: boolean;

  // Permissions & Flags
  canDelete?: boolean;
  isSocialShieldEnabled?: boolean;

  // Interactivity
  onPress?: () => void;
  onLike: () => void;
  onResonate: () => void;
  onComment: () => void;
  onReport?: () => void;
  onAuthorPress?: () => void;
  onShare: () => void;
  onDelete?: () => void;
  onBlock?: () => void;
  toggleMenu: () => void;

  // Poll Specifics
  pollProps?: {
    counts: Record<string, number>;
    userVotes: Set<string>;
    totalVotes: number;
    isLoading?: boolean;
    isVoting?: boolean;
    onVote: (optionId: string) => void;
    onRefresh?: () => void;
