export const PostCard = React.memo(function PostCard({
  post,
  currentUserId,
  isLiked,
  likeCount,
  hasResonated,
  isResonating,
  isMenuOpen,
  canDelete = false,
  isSocialShieldEnabled = false,
  onPress,
  onLike,
  onResonate,
  onComment,
  onReport,
  onAuthorPress,
  onShare,
  onDelete,
  onBlock,
  toggleMenu,
  pollProps,
  renderFooterAddon,
}: PostCardProps) {
  const theme = useTheme();
  const {
    author,
    type,
    createdAt,
    mediaUrl,
    mediaType,
    isAnonymous,
    pollData,
    urgency,
    hasAcceptedAnswer,
    feedbackStatus,
    feedbackResponse,
    commentCount,
  } = post;

  const isAnnouncement = type === 'announcement';

  const renderMediaContent = () => {
    if (!mediaUrl) return null;

    if (mediaType === 'image') {
      return (
        <Box className="mt-2">
          <Box
            className="rounded-xl overflow-hidden border border-white/5 bg-phase-surface relative"
            style={{ height: MEDIA_HEIGHT }}
          >
            <Image source={{ uri: mediaUrl }} className="absolute inset-0" resizeMode="cover" />
          </Box>
