    return (
      <Pressable
        className="flex-row items-center px-3 py-2 rounded-xl border border-phase-interactive mt-2 self-start active:opacity-70 gap-2"
        accessibilityRole="link"
        accessibilityLabel={`View ${mediaLabel}`}
