/**
 * SanctuaryBackground
 *
 * The living backdrop of the app. Rendered ONCE at TabNavigator level,
 * behind all tab screens (which are transparent over it).
 *
 * High/Mid: Animated gradient mesh - 2 LinearGradient layers crossfading.
 * Low/Battery: Static LinearGradient snapshot - same palette, zero animation cost.
 *
 * Phase transitions: 2s crossfade between palettes.
 */

import { LinearGradient } from 'expo-linear-gradient';
import { useEffect, useRef } from 'react';
import { Animated, StyleSheet } from 'react-native';
import { View } from '../primitives';
import { useTheme } from '../hooks/useTheme';

export function SanctuaryBackground() {
  const { gradientNodes, animationsEnabled } = useTheme();

  // Two gradient layers for crossfade transition
  const fadeAnim = useRef(new Animated.Value(0)).current;
  const prevNodes = useRef<[string, string, string]>(gradientNodes);
  const currentNodes = useRef<[string, string, string]>(gradientNodes);

  useEffect(() => {
    if (!animationsEnabled) {
      // Static - just update immediately
      prevNodes.current = gradientNodes;
      currentNodes.current = gradientNodes;
      fadeAnim.setValue(1);
      return;
    }

    // Crossfade: prev layer stays, new layer fades in over 2s
    prevNodes.current = currentNodes.current;
    currentNodes.current = gradientNodes;

    fadeAnim.setValue(0);
    const animation = Animated.timing(fadeAnim, {
      toValue: 1,
      duration: 2000,
      useNativeDriver: true,
    });
    animation.start();

    return () => animation.stop();
    // Note: isDark theme-mode toggles DO trigger a crossfade here to ensure immediate reactive update
    // of the background gradient nodes.
  }, [fadeAnim, gradientNodes, animationsEnabled]); // Re-run when phase OR theme mode changes.

  return (
    <View style={StyleSheet.absoluteFillObject} pointerEvents="none">
      {/* Layer 0: Previous phase (fades out) */}
      <LinearGradient
        colors={prevNodes.current}
        start={{ x: 0.1, y: 0 }}
        end={{ x: 0.9, y: 1 }}
        style={StyleSheet.absoluteFillObject}
      />
      {/* Layer 1: Current phase (fades in) */}
      <Animated.View
        style={[StyleSheet.absoluteFillObject, { opacity: fadeAnim }]}
        pointerEvents="none"
      >
        <LinearGradient
          colors={currentNodes.current}
          start={{ x: 0.2, y: 0 }}
          end={{ x: 0.8, y: 1 }}
          style={StyleSheet.absoluteFillObject}
        />
      </Animated.View>
    </View>
  );
}

import type React from 'react';
import { Button, ButtonIcon, ButtonSpinner, ButtonText } from './ui/button';

interface SanctuaryButtonProps {
  onPress?: () => void;
  children: React.ReactNode;
  variant?: 'solid' | 'outline' | 'ghost' | 'link';
  isLoading?: boolean;
  isDisabled?: boolean;
  leftIcon?: React.ElementType;
  rightIcon?: React.ElementType;
  size?: 'xs' | 'sm' | 'md' | 'lg';
  fullWidth?: boolean;
  action?: 'primary' | 'secondary' | 'negative' | 'positive';
  style?: any;
  accessibilityLabel?: string;
  accessibilityHint?: string;
  className?: string;
  iconProps?: any;
}

export function SanctuaryButton({
  onPress,
  children,
  variant = 'solid',
  isLoading = false,
  isDisabled = false,
  leftIcon,
  rightIcon,
  size = 'md',
  fullWidth = false,
  action = 'primary',
  style,
  accessibilityLabel,
  accessibilityHint,
  className = '',
  iconProps,
}: SanctuaryButtonProps) {
  // Semantic Mapping using Phase Tokens
  const getBgClass = () => {
    if (variant === 'outline' || variant === 'ghost' || variant === 'link') return 'bg-transparent';
    switch (action) {
      case 'primary':
        return 'bg-phase-accent';
      case 'secondary':
        return 'bg-phase-interactive';
      case 'negative':
        return 'bg-phase-danger';
      case 'positive':
        return 'bg-phase-reward';
      default:
        return 'bg-phase-accent';
    }
  };

  const getTextClass = () => {
    if (variant === 'solid') {
      switch (action) {
        case 'primary':
          return 'text-phase-text-on-accent';
        case 'secondary':
          return 'text-phase-text-primary';
        case 'negative':
          return 'text-white';
        case 'positive':
          return 'text-phase-text-on-accent';
        default:
          return 'text-phase-text-on-accent';
      }
    }
    switch (action) {
      case 'primary':
        return 'text-phase-accent';
      case 'secondary':
        return 'text-phase-text-primary';
      case 'negative':
        return 'text-phase-danger';
      case 'positive':
        return 'text-phase-reward';
      default:
        return 'text-phase-accent';
    }
  };

  const getBorderClass = () => {
    if (variant !== 'outline') return 'border-transparent';
    switch (action) {
      case 'primary':
        return 'border-phase-accent';
      case 'secondary':
        return 'border-phase-surface';
      case 'negative':
        return 'border-phase-danger';
      case 'positive':
        return 'border-phase-reward';
      default:
        return 'border-phase-accent';
    }
  };

  const sizeClasses = {
    xs: 'h-8 px-2',
    sm: 'h-9 px-3',
    md: 'h-11 px-6',
    lg: 'h-14 px-8',
  };

  return (
    <Button
      className={`
                ${fullWidth ? 'w-full' : 'w-auto'}
                ${getBgClass()}
                ${getBorderClass()}
                ${variant === 'outline' ? 'border' : 'border-0'}
                ${sizeClasses[size]}
                ${isDisabled || isLoading ? 'opacity-40' : 'opacity-100'}
                active:opacity-80
                ${className}
            `}
      isDisabled={isDisabled || isLoading}
      onPress={onPress}
      style={style}
      accessibilityLabel={
        accessibilityLabel || (typeof children === 'string' ? children : undefined)
      }
      accessibilityHint={accessibilityHint}
      accessibilityState={{
        busy: isLoading,
        disabled: isDisabled || isLoading,
      }}
    >
      {isLoading ? (
        <ButtonSpinner className={`mr-2 ${getTextClass()}`} />
      ) : leftIcon ? (
        <ButtonIcon as={leftIcon} className={`mr-2 ${getTextClass()}`} {...iconProps} />
      ) : null}

      <ButtonText className={`font-semibold ${getTextClass()}`}>{children}</ButtonText>

      {!isLoading && rightIcon && (
        <ButtonIcon as={rightIcon} className={`ml-2 ${getTextClass()}`} {...iconProps} />
      )}
    </Button>
  );
}

