/**
 * SANCTUARY CARD - Reusable Card Component
 *
 * A versatile card component that follows sanctuary design principles:
 * - Organic corners (never sharp)
 * - Soft shadows when elevated
 * - Lift animation when pressable
 *
 * Philosophy: Simple, reusable foundation for UI cards
 */

import { type FC, useState } from 'react';
import { Platform } from 'react-native';
import Animated, { useAnimatedStyle, useSharedValue, withSpring } from 'react-native-reanimated';
import { Box, Pressable, Text, VStack } from '../gluestack';

// ============================================================================
// TYPES
// ============================================================================

interface SanctuaryCardProps {
  title?: string;
  children: any;
  footer?: any;
  onPress?: () => void;
  onLongPress?: () => void;
  href?: string;
  target?: '_blank' | '_self';
  elevated?: boolean;
  style?: any;
  accessibilityLabel?: string;
  className?: string;
}

// ============================================================================
// CONSTANTS
// ============================================================================

const LIFT_SCALE_NORMAL = 1.0;
const LIFT_SCALE_PRESSED = 1.02;

// ============================================================================
// MAIN COMPONENT
// ============================================================================

const SanctuaryCard: FC<SanctuaryCardProps> = ({
  title,
  children,
  footer,
  onPress,
  onLongPress,
  href,
  target = '_self',
  elevated = false,
  style,
  accessibilityLabel,
  className,
}) => {
  // Hover state - only meaningful on web (desktop pointer devices)
  const [hovered, setHovered] = useState(false);

  // Shared value for lift animation
  const scale = useSharedValue(LIFT_SCALE_NORMAL);

  // ============================================================================
  // ANIMATION: LIFT EFFECT (when pressable)
  // ============================================================================

  const animatedStyle = useAnimatedStyle(() => {
    return {
      transform: [{ scale: scale.value }],
    };
  });

  const handlePressIn = () => {
    if (onPress || href) {
      scale.value = withSpring(LIFT_SCALE_PRESSED, {
        damping: 15,
        stiffness: 150,
      });
    }
  };

  const handlePressOut = () => {
    if (onPress || href) {
      scale.value = withSpring(LIFT_SCALE_NORMAL, {
        damping: 15,
        stiffness: 150,
      });
    }
  };

  // ============================================================================
  // RENDER: Container Level
  // ============================================================================

  const content = (
    <Animated.View
      style={[onPress || href ? animatedStyle : undefined, style]}
      className={`
                bg-phase-surface border border-white/5 rounded-3xl overflow-hidden
                ${elevated ? 'shadow-xl shadow-black/20' : ''}
                ${hovered && Platform.OS === 'web' ? 'opacity-90 scale-[1.01]' : ''}
                ${className || ''}
            `}
    >
      <VStack className="p-6">
        {/* Title Section */}
        {title && <Text className="text-xl font-bold text-phase-text-primary mb-4">{title}</Text>}

        {/* Children Content */}
        <Box className="gap-4">{children}</Box>

        {/* Footer Section */}
        {footer && (
          <VStack className="mt-4 gap-4">
            <Box className="h-px bg-white/5 opacity-30" />
            {footer}
          </VStack>
        )}
      </VStack>
    </Animated.View>
  );

  if (onPress || href) {
    return (
      <Pressable
        onPress={onPress}
        onLongPress={onLongPress}
        onPressIn={handlePressIn}
        onPressOut={handlePressOut}
        onHoverIn={Platform.OS === 'web' ? () => setHovered(true) : undefined}
        onHoverOut={Platform.OS === 'web' ? () => setHovered(false) : undefined}
        accessibilityRole={href ? 'link' : 'button'}
        accessibilityLabel={accessibilityLabel}
        href={href}
        hrefAttrs={{
          target: target,
          rel: target === '_blank' ? 'noopener noreferrer' : undefined,
        }}
      >
        {content}
      </Pressable>
    );
  }

  return content;
};

export { SanctuaryCard, SanctuaryCard as Card };

import { FlashList, type FlashListProps } from '@shopify/flash-list';
import { BookOpen } from 'lucide-react-native';
import React, { useCallback } from 'react';
import { type StyleProp, type ViewStyle } from 'react-native';
import { RefreshControl } from '../primitives';
import { useThemedColors } from '../hooks/useThemedColors';
import { Theme } from '../theme/Theme';
import EmptyState from './EmptyState';

export interface SanctuaryFlashListProps<T> extends Omit<FlashListProps<T>, 'refreshControl'> {
  /** Estimated size of a single list item (Optional in v2, Auto-calculated) */
  estimatedItemSize?: number;
  /** Whether the list is currently refreshing */
  refreshing?: boolean;
  /** Function to call when refreshing */
  onRefresh?: () => void;
  /** Optional empty state content */
  emptyComponent?: React.ReactElement;
  /** Color of the refresh spinner */
  refreshColor?: string;
  /** Style for the content container */
  contentContainerStyle?: StyleProp<ViewStyle>;
}

/**
 * SanctuaryFlashList - A high-performance list component optimized for component recycling.
 *
 * Philosophy: Performance is silent but essential for presence.
 * This component wraps @shopify/flash-list with Sanctuary-themed defaults.
 *
 * @example
 * <SanctuaryFlashList
 *   data={resources}
 *   renderItem={({ item }) => <ResourceRow resource={item} />}
 *   estimatedItemSize={Theme.listSizes.resourceRow}
 * />
 */
export function SanctuaryFlashList<T>({
  data,
  renderItem,
  estimatedItemSize,
  refreshing = false,
  onRefresh,
  emptyComponent,
  refreshColor,
  contentContainerStyle,
  ListEmptyComponent,
  ...props
}: SanctuaryFlashListProps<T>) {
  const _colors = useThemedColors();

  const renderEmpty = useCallback(() => {
    if (emptyComponent) return emptyComponent;

    if (ListEmptyComponent) {
      if (React.isValidElement(ListEmptyComponent)) return ListEmptyComponent;
      const EmptyComp = ListEmptyComponent as any;
      return <EmptyComp />;
    }

    return (
      <EmptyState
        icon={BookOpen}
        title="Silence in the Sanctuary"
        description="Your first discovery is waiting to be found here."
      />
    );
  }, [emptyComponent, ListEmptyComponent]);

  return (
    <FlashList
      {...(props as any)}
      data={data}
      renderItem={renderItem}
      estimatedItemSize={estimatedItemSize}
      ListEmptyComponent={renderEmpty}
      contentContainerStyle={[{ paddingBottom: Theme.spacing.xl }, contentContainerStyle]}
      refreshControl={
        onRefresh ? (
          <RefreshControl
            refreshing={refreshing}
            onRefresh={onRefresh}
            tintColor={refreshColor || Theme.colors.sanctuarySaffron}
            colors={[refreshColor || Theme.colors.sanctuarySaffron]}
          />
        ) : undefined
      }
    />
  );
}

export default SanctuaryFlashList;

/**
 * Web fallback for SanctuaryFlashList.
 *
 * @shopify/flash-list is optimised for native recycler views and does not have
 * reliable web support.  On web Metro resolves this .web.tsx file instead of
 * SanctuaryFlashList.tsx, swapping FlashList for React Native's built-in
 * FlatList which works correctly on all platforms.
 *
 * The public API (props) is kept identical so every call site compiles without
 * changes.
 */

import { BookOpen } from 'lucide-react-native';
import React, { useCallback } from 'react';
import { type StyleProp, type ViewStyle } from 'react-native';
import { FlatList, RefreshControl } from '../primitives';
import { useThemedColors } from '../hooks/useThemedColors';
import { Theme } from '../theme/Theme';
import EmptyState from './EmptyState';
import type { SanctuaryFlashListProps } from './SanctuaryFlashList';

function SanctuaryFlashListWeb<T>({
  data,
  renderItem,
  // eslint-disable-next-line @typescript-eslint/no-unused-vars
  estimatedItemSize: _estimatedItemSize, // API compatibility only - FlatList doesn't require it
  refreshing = false,
  onRefresh,
  emptyComponent,
  refreshColor,
  contentContainerStyle,
  ListEmptyComponent,
  ...props
}: SanctuaryFlashListProps<T>) {
  const _colors = useThemedColors();

  const renderEmpty = useCallback(() => {
    if (emptyComponent) return emptyComponent;

    if (ListEmptyComponent) {
      if (React.isValidElement(ListEmptyComponent)) return ListEmptyComponent;
      const EmptyComp = ListEmptyComponent as any;
      return <EmptyComp />;
    }

    return (
      <EmptyState
        icon={BookOpen}
        title="Silence in the Sanctuary"
        description="Your first discovery is waiting to be found here."
      />
    );
  }, [emptyComponent, ListEmptyComponent]);

  return (
    <FlatList
      {...(props as any)}
      data={data}
      renderItem={renderItem}
      ListEmptyComponent={renderEmpty}
      contentContainerStyle={[
        { paddingBottom: Theme.spacing.xl },
        contentContainerStyle as StyleProp<ViewStyle>,
      ]}
      refreshControl={
        onRefresh ? (
          <RefreshControl
            refreshing={refreshing}
            onRefresh={onRefresh}
            tintColor={refreshColor || Theme.colors.sanctuarySaffron}
            colors={[refreshColor || Theme.colors.sanctuarySaffron]}
          />
        ) : undefined
      }
    />
  );
}

