      --tab-bg:             ${isDark ? 'rgba(255,255,255,0.06)' : 'rgba(0,0,0,0.04)'};
      --tab-bg-hover:       ${isDark ? 'rgba(255,255,255,0.10)' : 'rgba(0,0,0,0.07)'};
      --tab-active-bg:      ${isDark ? 'rgba(58,122,154,0.22)' : 'rgba(58,122,154,0.10)'};
      --mobile-panel-bg:    ${scene.chrome.bg};

      /* Ink */
      --ink:         ${text.onCanvas};
      --ink-soft:    ${text.secondary};
      --ink-ghost:   #7a7068;
      --error:       #FF6347;

      /* Borders & Shadows */
      --border:       ${scene.surface.border};
      --border-light: rgba(255,255,255,0.7);
      --shadow-sm:    0 2px 8px rgba(107,100,128,0.07);
      --shadow-md:    0 8px 24px rgba(107,100,128,0.10);
      --shadow-lg:    0 16px 48px rgba(107,100,128,0.14);

      /* Typography */
      --font-display:'IM Fell English', serif;
      --font-body:   'DM Sans', sans-serif;

      /* Layout */
      --top-bar-h:   64px;
      --sidebar-w:   240px;
      --bp-mobile:   768px;
      --bp-tablet:   768px;
      --bp-desktop:  1024px;

      /* Legacy bridge tokens */
      --sanctuary-primary: ${gradientNodes[0]};
      --sanctuary-primary-rgb: ${isDark ? '26, 22, 16' : '245, 237, 214'};
      --sanctuary-text-primary: ${text.primary};
      --sanctuary-text-secondary: ${text.secondary};

      /* Motion */
      --transition-smooth: all 0.4s cubic-bezier(0.175, 0.885, 0.32, 1.275);
      --transition-snap:   all 0.2s cubic-bezier(0.4, 0, 0.2, 1);
    }
  `;

  // -- Static CSS: injected once on mount, never re-renders
  const staticInjectedRef = React.useRef(false);
  React.useInsertionEffect(() => {
    if (staticInjectedRef.current) return;
    staticInjectedRef.current = true;
    let el = document.getElementById('sanctuary-static-css') as HTMLStyleElement | null;
    if (!el) {
      el = document.createElement('style');
      el.id = 'sanctuary-static-css';
      el.textContent = STATIC_CSS;
      document.head.appendChild(el);
    }
  }, []);

  // -- Dynamic CSS: only the :root variables block, re-runs on theme change
  React.useInsertionEffect(() => {
    let el = document.getElementById('sanctuary-dynamic-css') as HTMLStyleElement | null;
    if (!el) {
      el = document.createElement('style');
      el.id = 'sanctuary-dynamic-css';
      document.head.appendChild(el);
    }
    el.textContent = dynamicCss;
  }, [dynamicCss]);

  return null;
}

import { AlertCircle } from 'lucide-react-native';
import type React from 'react';
import { Theme } from '../theme/Theme';
import {
  FormControl,
  FormControlError,
  FormControlErrorIcon,
  FormControlErrorText,
  FormControlLabel,
  FormControlLabelText,
  HStack,
  Input,
  InputField,
  InputIcon,
  InputSlot,
  Text,
  useFormControlContext,
} from './ui';

interface SanctuaryInputProps {
  label?: string;
  placeholder?: string;
  value: string;
  onChangeText: (text: string) => void;
  error?: string;
  isInvalid?: boolean;
  type?: 'text' | 'password';
  leftIcon?: React.ElementType;
  rightIcon?: React.ElementType;
  onRightIconPress?: () => void;
  helperText?: string;
  isDisabled?: boolean;
  multiline?: boolean;
  numberOfLines?: number;
  keyboardType?:
    | 'default'
    | 'number-pad'
    | 'decimal-pad'
    | 'numeric'
    | 'email-address'
    | 'phone-pad';
  accessibilityLabel?: string;
  accessibilityHint?: string;
}

/**
 * SanctuaryInput
 *
 * A hardened, phase-aware input component.
 * Uses NativeWind for styling and hardened gluestack primitives.
 */
export default function SanctuaryInput({
  label,
  placeholder,
  value,
  onChangeText,
  error,
  isInvalid = false,
  type = 'text',
  leftIcon,
  rightIcon,
  onRightIconPress,
  helperText,
  isDisabled = false,
  multiline = false,
  numberOfLines = 1,
  keyboardType = 'default',
  accessibilityLabel,
  accessibilityHint,
}: SanctuaryInputProps) {
  const { id } = useFormControlContext();
  const hasError = isInvalid || !!error;

  return (
    <FormControl isInvalid={hasError} isDisabled={isDisabled} className="w-full">
      {label && (
        <FormControlLabel className="mb-2">
          <HStack className="justify-between items-center w-full">
            <FormControlLabelText className="text-phase-text-primary font-medium tracking-wide">
              {label}
            </FormControlLabelText>
            {helperText && !hasError && (
              <Text className="text-[10px] text-phase-text-secondary uppercase tracking-widest font-bold">
                {helperText}
              </Text>
            )}
          </HStack>
        </FormControlLabel>
      )}

      <Input
        isDisabled={isDisabled}
        isInvalid={hasError}
        className="bg-phase-surface border-phase-surface focus:border-phase-accent h-12 rounded-xl"
      >
        {leftIcon && (
          <InputSlot className="pl-3">
            <InputIcon as={leftIcon} className="text-phase-text-secondary" />
          </InputSlot>
        )}

        <InputField
          placeholder={placeholder}
          placeholderTextColor={Theme.colors.shadowViolet}
          value={value}
          onChangeText={onChangeText}
          secureTextEntry={type === 'password'}
          keyboardType={keyboardType as any}
          className="text-phase-text-primary px-3 text-base"
          multiline={multiline}
          numberOfLines={numberOfLines}
          accessibilityLabel={accessibilityLabel || label}
          accessibilityHint={accessibilityHint}
          aria-labelledby={id ? `${id}-label` : undefined}
          aria-describedby={hasError && id ? `${id}-error` : undefined}
        />

        {rightIcon && (
          <InputSlot onPress={onRightIconPress} className="pr-3">
            <InputIcon
              as={rightIcon}
              className="text-phase-text-secondary active:text-phase-accent"
            />
          </InputSlot>
        )}
      </Input>

      {hasError && (
        <FormControlError className="mt-2">
          <FormControlErrorIcon as={AlertCircle} className="text-phase-danger" />
          <FormControlErrorText className="text-phase-danger text-sm">
            {error || 'Invalid input'}
          </FormControlErrorText>
        </FormControlError>
      )}
    </FormControl>
  );
}

import { X } from 'lucide-react-native';
import type React from 'react';
import { Pressable } from '../primitives';
import {
  HStack,
  Modal,
  ModalBody,
