export interface SanctuaryModalProps {
  /** Controls visibility */
  isOpen: boolean;
  /** Called when the modal requests to close */
  onClose: () => void;
  /** Modal title - shown in header */
  title: string;
  /** Optional subtitle below the title */
  subtitle?: string;
