}

/**
 * WebScreenHeader - Standardized greeting section for Web screens.
 * Uses CSS classes defined in SanctuaryGlobalStyles.
 */
export const WebScreenHeader: React.FC<WebScreenHeaderProps> = ({
  title,
  note,
  timeText,
  actions,
  showPersonalizedGreeting,
}) => {
  const { t } = useTranslation();
  const { context, can } = usePermissions();
  const { roles } = context;
  const { user } = useStore();

  // Determine greeting based on time of day (DRY from GlobalHeader)
  const getGreetingDetails = () => {
    const hour = new Date().getHours();
    if (hour < 12) return { text: t('goodMorning'), emoji: '≡ƒîà' };
    if (hour < 18) return { text: t('goodAfternoon'), emoji: 'ΓÿÇ∩╕Å' };
    return { text: t('goodEvening'), emoji: '≡ƒÅ«' };
  };

  const { text: greetingText, emoji } = getGreetingDetails();

  // Determine personalized greeting if requested
  let displayTimeText = timeText || greetingText;
  if (showPersonalizedGreeting) {
    const userName =
      (user as any)?.user_metadata?.full_name?.split(' ')[0] ||
      user?.full_name?.split(' ')[0] ||
      '';
    const roleLabel = roles[0] ? roles[0].charAt(0).toUpperCase() + roles[0].slice(1) : '';

    if (can('manage', 'TeacherDashboard') || can('manage', 'PrincipalDashboard')) {
      displayTimeText = `${greetingText}, ${roleLabel}`;
    } else {
      displayTimeText = `${greetingText}, ${userName}`;
    }
  }

  return (
    <header
      className="greeting"
      style={{
        display: 'flex',
        justifyContent: 'space-between',
        alignItems: 'flex-end',
        flexWrap: 'wrap',
        gap: '16px',
      }}
    >
      <div aria-live="polite" aria-atomic="true">
        <div className="greeting-time" aria-label={`${displayTimeText} ${emoji}`}>
          {displayTimeText} {emoji}
        </div>
        <h1 className="greeting-main">{title}</h1>
        {note && <p className="greeting-note">{note}</p>}
      </div>
      {actions && (
        <nav
          aria-label="Header Actions"
          style={{ display: 'flex', gap: '10px', paddingBottom: '4px' }}
        >
          {actions}
        </nav>
      )}
    </header>
  );
};

import { type FeatureFlags, useAuthStore, useFeatureStore } from '@repo/core/logic';
import type React from 'react';
import { Box, HStack, ScrollView, Switch, Text, VStack } from '../../gluestack';

/**
 * FeatureOverridesPanel - Developer Tooling for Flag Toggling.
 *
 * FAANG Principle: "Fast Iteration". Allow developers to test 'Locked'
 * features without changing database records.
 *
 * New Pattern: Using NativeWind (className) instead of legacy sx props.
 */
export const FeatureOverridesPanel: React.FC = () => {
  const { flags, recomputeFlags } = useFeatureStore();
  const { user, setUser } = useAuthStore();

  const toggleFlag = (key: keyof FeatureFlags, value: boolean) => {
    if (!user) return;

    // Inject override into user context flags
    const updatedUser = {
      ...user,
      flags: {
        // @ts-expect-error - Handle possible missing flags object in older user schema
        ...(user.flags || {}),
        [key]: value,
      },
    };

    // Update local store - using direct setState to ensure reactivity
    setUser(updatedUser as any);

    // Force recompute
    recomputeFlags(updatedUser as any);
  };

  return (
    <ScrollView>
      <Box className="p-4 bg-backgroundLight50 rounded-xl border border-borderLight100">
        <Text className="text-xl font-bold mb-2 text-textLight900">Feature Overrides</Text>
        <Text className="text-xs text-textLight500 mb-6">
          Toggle features for the current session. These overrides are stored in your local user
          state.
        </Text>

        <VStack space="lg">
          {Object.entries(flags).map(([key, value]) => (
            <HStack
              key={key}
              className="justify-between items-center bg-white p-3 rounded-md shadow-sm"
            >
              <VStack className="flex-1">
                <Text className="text-sm font-bold text-textLight800">{key}</Text>
                <Text className="text-xs text-textLight500">{value ? 'Active' : 'Disabled'}</Text>
              </VStack>
              <Switch
                value={value as boolean}
                onValueChange={(val: boolean) => toggleFlag(key as keyof FeatureFlags, val)}
              />
            </HStack>
          ))}
        </VStack>
      </Box>
    </ScrollView>
  );
};

