import { useCallback, useReducer } from 'react';
import { HStack, Input, InputField, VStack } from '../../primitives';
import { SanctuaryButton } from '../SanctuaryButton';
import SanctuaryModal from '../SanctuaryModal';

// ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
// ASSET CREATION MODAL
// ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

interface AssetFormState {
  title: string;
  url: string;
  description: string;
  tags: string;
}

type AssetAction =
  | { type: 'SET_FIELD'; field: keyof AssetFormState; value: string }
  | { type: 'RESET' };

function assetReducer(state: AssetFormState, action: AssetAction): AssetFormState {
  switch (action.type) {
    case 'SET_FIELD':
      return { ...state, [action.field]: action.value };
    case 'RESET':
      return { title: '', url: '', description: '', tags: '' };
    default:
      return state;
  }
}

/**
 * AssetCreationModal - Standard Platform Entry Point
 */
export function AssetCreationModal({
  isOpen,
  onClose,
  onAdd,
  title = 'Add New Asset',
  placeholders = {},
}: {
  isOpen: boolean;
  onClose: () => void;
  onAdd: (data: any) => void;
  title?: string;
  placeholders?: Record<string, string>;
}) {
  const [formData, dispatch] = useReducer(assetReducer, {
    title: '',
    url: '',
    description: '',
    tags: '',
  });

  const handleSetTitle = useCallback((t: string) => dispatch({ type: 'SET_FIELD', field: 'title', value: t }), []);
  const handleSetUrl = useCallback((u: string) => dispatch({ type: 'SET_FIELD', field: 'url', value: u }), []);
  const handleSetDescription = useCallback((d: string) => dispatch({ type: 'SET_FIELD', field: 'description', value: d }), []);

  const handleAdd = useCallback(() => {
    if (!formData.title || !formData.url) return;
    onAdd({ ...formData, tags: formData.tags.split(',').map((t) => t.trim()) });
    onClose();
    dispatch({ type: 'RESET' });
  }, [formData, onAdd, onClose]);

  return (
    <SanctuaryModal isOpen={isOpen} onClose={onClose} title={title}>
      <VStack className="gap-5 p-2">
        <Input className="h-14">
          <InputField
            placeholder={placeholders['title'] || 'Asset Title'}
            value={formData.title}
            onChangeText={handleSetTitle}
          />
        </Input>
        <Input className="h-14">
          <InputField
            placeholder={placeholders['url'] || 'Reference URL'}
            value={formData.url}
            onChangeText={handleSetUrl}
            autoCapitalize="none"
          />
        </Input>
        <Input className="min-h-[100px]">
          <InputField
            placeholder={placeholders['description'] || 'Description (Optional)'}
            value={formData.description}
            onChangeText={handleSetDescription}
            multiline
          />
        </Input>
        <HStack className="justify-end gap-3 pt-4">
          <SanctuaryButton variant="ghost" onPress={onClose}>
            Dismiss
          </SanctuaryButton>
          <SanctuaryButton onPress={handleAdd} isDisabled={!formData.title || !formData.url}>
            Complete
          </SanctuaryButton>
        </HStack>
      </VStack>
    </SanctuaryModal>
  );
}

// ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
// COLLECTION CREATION MODAL
// ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

interface CollectionState {
  name: string;
  description: string;
  loading: boolean;
}

type CollectionAction =
  | { type: 'SET_NAME'; name: string }
  | { type: 'SET_DESCRIPTION'; description: string }
  | { type: 'SET_LOADING'; loading: boolean }
  | { type: 'RESET' };

function collectionReducer(state: CollectionState, action: CollectionAction): CollectionState {
  switch (action.type) {
    case 'SET_NAME':
      return { ...state, name: action.name };
    case 'SET_DESCRIPTION':
      return { ...state, description: action.description };
    case 'SET_LOADING':
      return { ...state, loading: action.loading };
    case 'RESET':
      return { name: '', description: '', loading: false };
    default:
      return state;
  }
}

/**
 * CollectionCreationModal - Standard Platform Organizer
 */
export function CollectionCreationModal({
  isOpen,
  onClose,
  onSubmit,
  title = 'Create Collection',
}: {
  isOpen: boolean;
  onClose: () => void;
  onSubmit: (data: { name: string; description: string }) => Promise<void>;
  title?: string;
}) {
  const [state, dispatch] = useReducer(collectionReducer, {
    name: '',
    description: '',
    loading: false,
  });

  const { name, description, loading } = state;

  const handleSetName = useCallback((val: string) => dispatch({ type: 'SET_NAME', name: val }), []);
  const handleSetDescription = useCallback((val: string) => dispatch({ type: 'SET_DESCRIPTION', description: val }), []);

  const handleComplete = useCallback(async () => {
    if (!name.trim()) return;
    dispatch({ type: 'SET_LOADING', loading: true });
    try {
      await onSubmit({ name, description });
      dispatch({ type: 'RESET' });
      onClose();
    } finally {
      dispatch({ type: 'SET_LOADING', loading: false });
    }
  }, [name, description, onSubmit, onClose]);

  return (
    <SanctuaryModal isOpen={isOpen} onClose={onClose} title={title}>
      <VStack className="gap-5 p-2">
        <Input className="h-14">
          <InputField placeholder="Collection Name" value={name} onChangeText={handleSetName} />
        </Input>
        <Input className="min-h-[100px]">
          <InputField
            placeholder="Description"
            value={description}
            onChangeText={handleSetDescription}
            multiline
          />
        </Input>
        <HStack className="justify-end gap-3 pt-4">
          <SanctuaryButton variant="ghost" onPress={onClose}>
            Cancel
          </SanctuaryButton>
          <SanctuaryButton onPress={handleComplete} isLoading={loading} isDisabled={!name.trim()}>
            Create
          </SanctuaryButton>
        </HStack>
      </VStack>
    </SanctuaryModal>
  );
}

import type { DownloadState } from '@repo/core/hooks';
import { Bookmark, Download, ExternalLink, XCircle } from 'lucide-react-native';
import { useTheme } from '../../hooks/useTheme';
import { Box, HStack, Text, VStack } from '../../primitives';
import GlobalHeader from '../GlobalHeader';
import { SanctuaryButton } from '../SanctuaryButton';
import ScreenWrapper from '../ScreenWrapper';

export interface PdfViewerProps {
  title: string;
  subtitle?: string;
  downloadState: DownloadState;
  progress: number;
  errorMsg?: string | null;
  onDownload: () => void;
  onOpen: () => void;
  onBack: () => void;
  isBookmarked?: boolean;
  onToggleBookmark?: () => void;
}

/**
 * PdfViewer - Foundational component for document rendering.
 * Encapsulates the "Download and View" workflow with Sanctuary V3 aesthetics.
 */
export function PdfViewer({
  title,
  subtitle = 'Institutional Document',
  downloadState,
  progress,
  errorMsg,
  onDownload,
  onOpen,
  onBack,
  isBookmarked,
  onToggleBookmark,
}: PdfViewerProps) {
  const theme = useTheme();

  return (
    <ScreenWrapper scroll={false} className="bg-phase-surface">
      <GlobalHeader
        title={title}
        subtitle={subtitle}
        showBack
        onBack={onBack}
        rightAction={
          onToggleBookmark && (
            <Box className={`rounded-full ${isBookmarked ? 'bg-phase-accent/20' : ''}`}>
              <SanctuaryButton
                variant="ghost"
                size="sm"
                leftIcon={Bookmark}
                onPress={onToggleBookmark}
                accessibilityLabel={isBookmarked ? 'Remove bookmark' : 'Bookmark document'}
                className={isBookmarked ? 'opacity-100' : 'opacity-60'}
              >
                {''}
              </SanctuaryButton>
            </Box>
          )
        }
      />

      <VStack className="flex-1 items-center justify-center p-8">
        {/* Icon area */}
        <Box className="w-32 h-32 rounded-3xl bg-phase-accent/10 items-center justify-center mb-8 border border-phase-accent/20">
          <Download size={48} color={theme.accent.action} />
        </Box>

        <Text className="text-2xl font-bold text-phaseText-primary text-center mb-2">{title}</Text>
        <Text className="text-md text-phaseText-secondary text-center mb-10 leading-6">
          Open this document in your device's native PDF viewer for the best reading experience.
        </Text>

        {/* Progress bar - shown while downloading */}
        {downloadState === 'downloading' && (
          <Box className="w-full mb-8">
            <Box className="h-1.5 w-full bg-white/10 rounded-full overflow-hidden">
              <Box
                className="h-full rounded-full bg-phase-accent"
                style={{ width: `${Math.round(progress * 100)}%` }}
              />
            </Box>
            <Text className="text-xs text-phaseText-tertiary text-center mt-2 font-mono">
              {Math.round(progress * 100)}%
            </Text>
          </Box>
        )}

        {errorMsg && (
          <HStack className="items-center gap-2 mb-6 p-4 bg-phase-danger/10 rounded-2xl border border-phase-danger/20">
            <XCircle size={16} color={theme.scene.danger.main} />
            <Text className="text-sm text-phase-danger font-medium">{errorMsg}</Text>
          </HStack>
        )}

        {/* Action buttons */}
        {downloadState === 'idle' || downloadState === 'error' ? (
          <SanctuaryButton
            onPress={onDownload}
            leftIcon={Download}
            accessibilityLabel="Download and open PDF"
            className="px-10"
          >
            Download Document
          </SanctuaryButton>
        ) : downloadState === 'ready' ? (
          <VStack className="w-full gap-4">
            <SanctuaryButton
              onPress={onOpen}
              leftIcon={ExternalLink}
              accessibilityLabel="Open in native viewer"
              fullWidth
            >
              Open in Viewer
            </SanctuaryButton>
            <SanctuaryButton
              variant="outline"
              onPress={onDownload}
              leftIcon={Download}
              accessibilityLabel="Re-download PDF"
              fullWidth
            >
              Refetch Document
            </SanctuaryButton>
          </VStack>
        ) : null}
      </VStack>
    </ScreenWrapper>
  );
}

import type { BaseResource } from '@repo/core/types';
import { Bookmark, FileText, FolderPlus, Info, PlayCircle, Share2 } from 'lucide-react-native';
import type React from 'react';
import {
  Actionsheet,
  ActionsheetBackdrop,
  ActionsheetContent,
  ActionsheetDragIndicator,
  ActionsheetDragIndicatorWrapper,
  ActionsheetIcon,
  ActionsheetItem,
  ActionsheetItemText,
  Box,
  HStack,
  Pressable,
  ScrollView,
  Text,
  VStack,
} from '../../gluestack';
import { useTheme } from '../../hooks/useTheme';

export interface ResourceActionSheetProps {
  visible: boolean;
  onClose: () => void;
  resource: BaseResource & { has_bookmarked?: boolean };
  onBookmark: () => void;
  onAddToCollection?: () => void;
  onShare: () => void;
  onViewDetails?: () => void;
}

/**
 * ResourceActionSheet - Standard platform-wide interaction sheet for digital assets.
 * Adheres to Sanctuary V3 spatial design patterns.
 */
export const ResourceActionSheet: React.FC<ResourceActionSheetProps> = ({
  visible,
  onClose,
  resource,
  onBookmark,
  onAddToCollection,
  onShare,
  onViewDetails,
}) => {
  const theme = useTheme();
  if (!resource) return null;

  return (
    <Actionsheet isOpen={visible} onClose={onClose}>
      <ActionsheetBackdrop />
      <ActionsheetContent className="pb-10 px-4">
        <ActionsheetDragIndicatorWrapper>
          <ActionsheetDragIndicator />
        </ActionsheetDragIndicatorWrapper>

        <HStack className="items-center py-4 border-b border-phase-border mb-2 gap-3 w-full">
          <Box className="w-12 h-12 items-center justify-center rounded-xl bg-phase-accent/10">
            {resource.type === 'video' ? (
              <PlayCircle size={28} color={theme.accent.action} />
            ) : (
              <FileText size={28} color={theme.accent.action} />
            )}
          </Box>
          <VStack className="flex-1">
            <Text className="text-xl font-bold text-phaseText-primary" numberOfLines={1}>
              {resource.title}
            </Text>
            <Text className="text-xs text-phaseText-tertiary uppercase tracking-wider font-bold">
              {resource.type} Resource
            </Text>
          </VStack>
        </HStack>

        <ScrollView className="w-full mb-4">
          {onViewDetails && (
            <ActionsheetItem
              onPress={() => {
                onViewDetails();
                onClose();
              }}
              className="rounded-2xl"
            >
              <ActionsheetIcon>
                <Info size={22} color={theme.text.secondary} />
              </ActionsheetIcon>
              <ActionsheetItemText>View Details</ActionsheetItemText>
            </ActionsheetItem>
          )}

          <ActionsheetItem
            onPress={() => {
              onBookmark();
              onClose();
            }}
            className="rounded-2xl"
          >
            <ActionsheetIcon>
              <Bookmark
                size={22}
                color={resource.has_bookmarked ? theme.accent.action : theme.text.secondary}
                fill={resource.has_bookmarked ? theme.accent.action : 'transparent'}
              />
            </ActionsheetIcon>
            <ActionsheetItemText
              className={resource.has_bookmarked ? 'text-phase-accent font-bold' : ''}
            >
              {resource.has_bookmarked ? 'Bookmarked' : 'Bookmark'}
            </ActionsheetItemText>
          </ActionsheetItem>

