import { useCallback, useEffect, useReducer, useRef } from 'react';
import { Pressable, Box, HStack, Text, VStack } from '../../primitives';
import Animated, { FadeInUp } from 'react-native-reanimated';
import { useTheme } from '../../hooks/useTheme';
import { formatTimeMs } from '../../utils/dateTimeUtils';
import { SanctuaryButton } from '../SanctuaryButton';

export interface VideoPlayerProps {
  url: string;
  title?: string;
  creator?: string;
  onClose?: () => void;
}

/**
 * VideoPlayer - Premium, platform-standard video consumption shell.
 * Uses expo-video for high-performance native playback.
 */
export function VideoPlayer({ url, title, creator, onClose }: VideoPlayerProps) {
  const theme = useTheme();
  const progressBarWidth = useRef<number>(0);

  const [state, dispatch] = useReducer(mediaReducer, mediaInitialState);
  const { isPlaying, positionMillis, durationMillis, showControls, hasError } = state;

  // Sync status bar visibility
  useEffect(() => {
    coreRuntime.ui.setStatusBarHidden(!showControls, 'fade');
    return () => {
      coreRuntime.ui.setStatusBarHidden(false, 'fade');
    };
  }, [showControls]);

  // Initialise expo-video player
  const player = useVideoPlayer(url, (p: any) => {
    p.loop = false;
    p.play();
  });

  // Sync state with player
  useEffect(() => {
    const interval = setInterval(() => {
      if (player) {
        dispatch({ type: 'SET_PLAYING', payload: player.playing });
        dispatch({
          type: 'SET_PROGRESS',
          position: player.currentTime * 1000,
          duration: player.duration * 1000,
        });
      }
    }, 500);

    return () => clearInterval(interval);
  }, [player]);

  const handlePlayPause = useCallback(() => {
    if (!player) return;
    if (isPlaying) {
      player.pause();
    } else {
      player.play();
    }
  }, [player, isPlaying]);

  const handleSeekBy = useCallback(
    (deltaMs: number) => {
      if (!player || durationMillis === 0) return;
      player.currentTime += deltaMs / 1000;
    },
    [player, durationMillis],
  );

  const handleProgressTap = useCallback(
    (x: number, barWidth: number) => {
      if (!player || durationMillis === 0 || barWidth === 0) return;
      const ratio = Math.max(0, Math.min(1, x / barWidth));
      player.currentTime = (ratio * durationMillis) / 1000;
    },
    [player, durationMillis],
  );

  const handleToggleControls = useCallback(() => {
    dispatch({ type: 'TOGGLE_CONTROLS' });
  }, []);

  const handleRewind = useCallback(() => handleSeekBy(-10000), [handleSeekBy]);
  const handleForward = useCallback(() => handleSeekBy(10000), [handleSeekBy]);

  const handleProgressBarPress = useCallback(
    (e: any) => {
      const { locationX } = e.nativeEvent;
      handleProgressTap(locationX, progressBarWidth.current);
    },
    [handleProgressTap],
  );

  const handleProgressBarLayout = useCallback((e: any) => {
    progressBarWidth.current = e.nativeEvent.layout.width;
  }, []);

  const progressPercentage = durationMillis > 0 ? (positionMillis / durationMillis) * 100 : 0;

  if (hasError || !url) {
    return (
      <Box className="flex-1 bg-black items-center justify-center">
        <Text className="text-white text-lg text-center p-8">
          Unable to load video. Please check the URL and try again.
        </Text>
        {onClose && (
          <SanctuaryButton onPress={onClose} leftIcon={X}>
            Close
          </SanctuaryButton>
        )}
      </Box>
    );
  }

  return (
    <Box className="flex-1 bg-black">
      <Pressable
        onPress={handleToggleControls}
        className="flex-1"
        accessibilityLabel="Toggle video controls visibility"
        accessibilityRole="button"
      >
        <VideoView
          player={player}
          className="absolute inset-0"
          contentFit="contain"
          nativeControls={false}
        />
      </Pressable>

      {showControls && (
        <Animated.View entering={FadeInUp} className="absolute inset-0" pointerEvents="box-none">
          <Box className="flex-1 bg-black/40 p-4">
            {/* Header */}
            <HStack className="justify-between items-center">
              <VStack className="flex-1 mr-4">
                {title && (
                  <Text className="text-white text-lg font-bold" numberOfLines={1}>
                    {title}
                  </Text>
                )}
                {creator && (
                  <Text className="text-phaseText-tertiary text-sm" numberOfLines={1}>
                    {creator}
                  </Text>
                )}
              </VStack>
              {onClose && (
                <SanctuaryButton
                  onPress={onClose}
                  variant="ghost"
                  size="sm"
                  leftIcon={X}
                  accessibilityLabel="Close video"
                >
                  {''}
                </SanctuaryButton>
              )}
            </HStack>

            {/* Centre play controls */}
            <Box className="flex-1 justify-center items-center">
              <HStack className="gap-8 items-center">
                <SanctuaryButton
                  variant="ghost"
                  leftIcon={RotateCcw}
                  onPress={handleRewind}
                  accessibilityLabel="Rewind 10 seconds"
                >
                  {''}
                </SanctuaryButton>
                <Pressable
                  onPress={handlePlayPause}
                  accessibilityLabel={isPlaying ? 'Pause video' : 'Play video'}
                  accessibilityRole="button"
                  className="w-20 h-20 rounded-full bg-phase-accent items-center justify-center shadow-lg"
                  style={{
                    shadowColor: theme.accent.action,
                    shadowRadius: 20,
                    shadowOpacity: 0.5,
                  }}
                >
                  {isPlaying ? (
                    <Pause color="white" size={40} fill="white" />
                  ) : (
                    <Play color="white" size={40} fill="white" />
                  )}
                </Pressable>
                <SanctuaryButton
                  variant="ghost"
                  leftIcon={RotateCw}
                  onPress={handleForward}
                  accessibilityLabel="Forward 10 seconds"
                >
                  {''}
                </SanctuaryButton>
              </HStack>
            </Box>

            {/* Footer: progress + time */}
            <VStack className="gap-2">
              <Pressable
                onPress={handleProgressBarPress}
                onLayout={handleProgressBarLayout}
                accessibilityLabel={`Seek video position. Progress is ${Math.round(
                  progressPercentage,
                )}%`}
                accessibilityRole="adjustable"
              >
                <Box className="h-1 w-full bg-white/20 rounded-sm overflow-hidden">
                  <Box
                    className="h-1 bg-phase-accent rounded-sm"
                    style={{ width: `${progressPercentage}%` }}
                  />
                </Box>
              </Pressable>

              <HStack className="justify-between items-center">
                <Text
                  className="text-white text-xs"
                  accessibilityLabel={`Current time ${formatTimeMs(positionMillis)} of ${formatTimeMs(
                    durationMillis,
                  )}`}
                >
                  {formatTimeMs(positionMillis)} / {formatTimeMs(durationMillis)}
                </Text>
              </HStack>
            </VStack>
          </Box>
        </Animated.View>
      )}
    </Box>
  );
}

import { mediaInitialState, mediaReducer } from '@repo/core/logic';
import { Pause, Play, RotateCcw, RotateCw, X } from 'lucide-react-native';
import type React from 'react';
import { useCallback, useEffect, useReducer, useRef } from 'react';
import { Pressable } from '../../primitives';
import { Box } from '../../components/ui/box';
import { HStack } from '../../components/ui/hstack';
import { Text } from '../../components/ui/text';
import { VStack } from '../../components/ui/vstack';
import { useTheme } from '../../hooks/useTheme';
import { formatTimeMs } from '../../utils/dateTimeUtils';
import { SanctuaryButton } from '../SanctuaryButton';

export interface VideoPlayerProps {
  url: string;
  title?: string;
  creator?: string;
  onClose?: () => void;
}

/**
 * VideoPlayer (Web) - Standard HTML5 video implementation with shared Sanctuary aesthetics.
 */
export function VideoPlayer({ url, title, creator, onClose }: VideoPlayerProps) {
  const theme = useTheme();
  const videoRef = useRef<HTMLVideoElement>(null);
  const progressBarRef = useRef<HTMLDivElement>(null);

  const [state, dispatch] = useReducer(mediaReducer, mediaInitialState);
  const { isPlaying, positionMillis, durationMillis, showControls, hasError } = state;

  useEffect(() => {
    const video = videoRef.current;
    if (!video) return;

    const handleTimeUpdate = () => {
      dispatch({
        type: 'SET_PROGRESS',
        position: video.currentTime * 1000,
        duration: video.duration * 1000,
      });
    };

    const handlePlay = () => dispatch({ type: 'SET_PLAYING', payload: true });
    const handlePause = () => dispatch({ type: 'SET_PLAYING', payload: false });
    const handleError = () => dispatch({ type: 'SET_ERROR', payload: true });

    video.addEventListener('timeupdate', handleTimeUpdate);
    video.addEventListener('play', handlePlay);
    video.addEventListener('pause', handlePause);
    video.addEventListener('error', handleError);

    return () => {
      video.removeEventListener('timeupdate', handleTimeUpdate);
      video.removeEventListener('play', handlePlay);
      video.removeEventListener('pause', handlePause);
      video.removeEventListener('error', handleError);
    };
  }, []);

  const handlePlayPause = useCallback(() => {
    const video = videoRef.current;
    if (!video) return;
    if (isPlaying) {
      video.pause();
    } else {
      video.play().catch(() => {
        // Handle play promise rejection (e.g. user hasn't interacted yet)
        dispatch({ type: 'SET_PLAYING', payload: false });
      });
    }
  }, [isPlaying]);

  const handleSeekBy = useCallback((deltaMs: number) => {
    const video = videoRef.current;
    if (!video) return;
    video.currentTime += deltaMs / 1000;
  }, []);

  const handleToggleControls = useCallback(() => {
    dispatch({ type: 'TOGGLE_CONTROLS' });
  }, []);

  const handleProgressBarClick = useCallback((e: React.MouseEvent<HTMLDivElement>) => {
    const bar = progressBarRef.current;
    const video = videoRef.current;
    if (!bar || !video) return;

    const rect = bar.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const ratio = Math.max(0, Math.min(1, x / rect.width));
    video.currentTime = ratio * video.duration;
  }, []);

  const progressPercentage = durationMillis > 0 ? (positionMillis / durationMillis) * 100 : 0;

  if (hasError || !url) {
    return (
      <Box className="flex-1 bg-black items-center justify-center h-full">
        <Text className="text-white text-lg text-center p-8">
          Unable to load video. Please check the URL and try again.
        </Text>
        {onClose && (
          <SanctuaryButton onPress={onClose} leftIcon={X}>
            Close
          </SanctuaryButton>
        )}
      </Box>
    );
  }

  return (
    <Box className="flex-1 bg-black relative w-full h-full group overflow-hidden">
      <video
        ref={videoRef}
        src={url}
        className="w-full h-full object-contain"
        onClick={handleToggleControls}
        autoPlay
      >
        <track kind="captions" />
      </video>

      {showControls && (
        <Box className="absolute inset-0 bg-black/40 p-4 transition-opacity duration-300 pointer-events-none">
          <Box className="flex-1 flex flex-col justify-between pointer-events-auto">
            {/* Header */}
            <HStack className="justify-between items-center">
              <VStack className="flex-1 mr-4">
                {title && <Text className="text-white text-lg font-bold">{title}</Text>}
                {creator && <Text className="text-phaseText-tertiary text-sm">{creator}</Text>}
              </VStack>
              {onClose && (
                <SanctuaryButton
                  onPress={onClose}
                  variant="ghost"
                  size="sm"
                  leftIcon={X}
                  accessibilityLabel="Close video"
                >
                  {''}
                </SanctuaryButton>
              )}
            </HStack>

            {/* Centre play controls */}
            <Box className="flex-1 flex items-center justify-center">
              <HStack className="gap-8 items-center">
                <SanctuaryButton
                  variant="ghost"
                  leftIcon={RotateCcw}
                  onPress={() => handleSeekBy(-10000)}
                >
                  {''}
                </SanctuaryButton>

                <Pressable
                  onPress={handlePlayPause}
                  className="w-20 h-20 rounded-full bg-phase-accent flex items-center justify-center shadow-lg hover:scale-105 transition-transform"
                  style={{
                    boxShadow: `0 0 20px ${theme.accent.action}80`,
                  }}
                >
                  {isPlaying ? (
                    <Pause color="white" size={40} fill="white" />
                  ) : (
                    <Play color="white" size={40} fill="white" />
                  )}
                </Pressable>

                <SanctuaryButton
                  variant="ghost"
                  leftIcon={RotateCw}
                  onPress={() => handleSeekBy(10000)}
                >
                  {''}
                </SanctuaryButton>
              </HStack>
            </Box>

            {/* Footer */}
            <VStack className="gap-2">
              <div
                ref={progressBarRef}
                onClick={handleProgressBarClick}
                onKeyDown={(e) => {
                  if (e.key === 'ArrowRight') handleSeekBy(5000);
                  if (e.key === 'ArrowLeft') handleSeekBy(-5000);
                  if (e.key === 'Enter' || e.key === ' ') handlePlayPause();
                }}
                role="slider"
                aria-label="Video progress"
                aria-valuemin={0}
                aria-valuemax={100}
                aria-valuenow={Math.round(progressPercentage)}
                tabIndex={0}
                className="h-1.5 w-full bg-white/20 rounded-full overflow-hidden cursor-pointer group/progress focus:outline-none focus:ring-2 focus:ring-phase-accent"
              >
                <div
                  className="h-full bg-phase-accent transition-all duration-100"
                  style={{ width: `${progressPercentage}%` }}
                />
              </div>

              <HStack className="justify-between items-center">
                <Text className="text-white text-xs">
                  {formatTimeMs(positionMillis)} / {formatTimeMs(durationMillis)}
                </Text>
              </HStack>
            </VStack>
          </Box>
        </Box>
      )}
    </Box>
  );
}

/**
 * COMMUNITY PRESENCE
 * Shows how many teachers/students are currently online based on role.
 * Refactored for Sanctuary V3.
 * Promoted to @repo/ui/components/social
 */

import { useEffect, useMemo } from 'react';
import { useTranslation } from 'react-i18next';
import Animated, {
  Easing,
  useAnimatedStyle,
  useSharedValue,
  withRepeat,
  withTiming,
} from 'react-native-reanimated';
import { Users, WifiOff } from '../../icons';
import { Box, Heading, HStack, Icon, Spinner, Text, View, VStack } from '../../primitives';

// These props will be consumed by the UI from its own internal hook or props
export interface CommunityPresenceProps {
  compact?: boolean;
  hidePadding?: boolean;
  userVibe?: string;
  onlineCount: number;
  isLoading: boolean;
  isOffline: boolean;
  perspective: 'student' | 'teacher' | 'principal';
}

export default function CommunityPresence({
  compact = false,
  hidePadding = false,
  userVibe = 'active',
  onlineCount,
  isLoading,
  isOffline,
  perspective,
}: CommunityPresenceProps) {
  const { t } = useTranslation();
  const dominantVibe = userVibe;

  const pulseScale = useSharedValue(1);
  const pulseOpacity = useSharedValue(0.6);

  useEffect(() => {
    pulseScale.value = withRepeat(
      withTiming(1.3, { duration: 2500, easing: Easing.inOut(Easing.ease) }),
      -1,
      true,
    );
    pulseOpacity.value = withRepeat(
      withTiming(0.2, { duration: 2500, easing: Easing.inOut(Easing.ease) }),
      -1,
      true,
    );
  }, [pulseOpacity, pulseScale]);

  const pulseStyle = useAnimatedStyle(() => ({
    transform: [{ scale: pulseScale.value }],
    opacity: pulseOpacity.value,
  }));

  const getVibeClass = (vibe: string) => {
    switch (vibe.toLowerCase()) {
      case 'active':
        return 'text-phase-interactive';
      case 'focused':
        return 'text-phase-interactive';
      case 'reflecting':
        return 'text-phase-interactive';
      case 'teaching':
        return 'text-ink';
      case 'planning':
        return 'text-phase-interactive';
      default:
        return 'text-ink/60';
    }
  };

  const vibeClass = useMemo(
    () => (isOffline ? 'text-ink/40' : getVibeClass(dominantVibe)),
    [isOffline, dominantVibe, getVibeClass],
  );

  const roleLabel = useMemo(() => {
    if (perspective === 'student') return t('community.students') || 'Students';
    if (perspective === 'principal') return t('community.members') || 'Members';
    return t('community.educators') || 'Educators';
  }, [perspective, t]);

  const motivationText = useMemo(() => {
    if (perspective === 'student')
      return t('community.studentMotivation') || 'You are not alone in your journey.';
    if (perspective === 'principal')
      return t('community.principalMotivation') || 'Maintaining the sanctuary together.';
    return t('community.teacherMotivation') || 'Guiding the future, together.';
  }, [perspective, t]);

  if (isLoading) {
    return (
      <HStack className={`items-center opacity-60 gap-3 ${hidePadding || compact ? 'p-0' : 'p-4'}`}>
        <Spinner />
        <Text className="text-ink/60 text-sm">Locating Sanctuary Presence...</Text>
      </HStack>
    );
  }

  if (compact) {
    return (
      <HStack className="items-center gap-2">
        <Box
          className={`w-2 h-2 rounded-full ${isOffline ? 'bg-ink/40' : 'bg-phase-interactive'}`}
        />
        <Text className="text-[12px] text-ink/60 font-bold">
          {isOffline ? t('community.offline') || 'Offline' : `${onlineCount} ${roleLabel}`}
        </Text>
      </HStack>
    );
  }

  return (
    <VStack className={`gap-4 ${hidePadding || compact ? 'p-0' : 'p-4'}`}>
      <HStack className="items-center gap-4">
        <View className="relative">
          {isOffline ? (
            <Icon as={WifiOff} className="text-ink/40" size="lg" />
          ) : (
            <Icon as={Users} className={vibeClass} size="lg" />
          )}
          {!isOffline && (
            <Animated.View style={pulseStyle}>
              <Box className="absolute -top-1 -right-1 w-3 h-3 rounded-full bg-phase-interactive" />
            </Animated.View>
          )}
        </View>
        <VStack className="gap-0.5">
          <Heading className="text-sm font-bold text-ink">
            {isOffline
              ? t('community.offlineTitle') || 'Connection Lost'
              : t('community.sanctuaryPulse') || 'Sanctuary Pulse'}
          </Heading>
          <Text className="text-ink/60 text-sm leading-snug">
            {isOffline
              ? t('community.offlineDesc') || 'You are viewing a static instance.'
              : `${onlineCount} ${roleLabel} ${t('community.onlineNow') || 'present now'}`}
          </Text>
          {!isOffline && (
            <Text className="text-ink/40 text-[11px] font-medium mt-0.5">
              {t('community.dominantVibe') || 'Dominant Vibe'}:{' '}
              <Text className="text-phase-interactive lowercase">{dominantVibe}</Text>
            </Text>
          )}
        </VStack>
      </HStack>

      {!isOffline && onlineCount > 0 && (
        <Box className="bg-phase-surface/50 p-4 rounded-2xl border border-border">
          <Text className="text-[12px] text-ink/60 italic leading-relaxed">"{motivationText}"</Text>
        </Box>
      )}
    </VStack>
  );
}

