  );
};

// --- Main Components ---

export interface ICheckboxProps extends ViewProps {
  value: string;
  isChecked?: boolean;
  isDisabled?: boolean;
  isInvalid?: boolean;
  onChange?: (checked: boolean) => void;
  children?: React.ReactNode;
  className?: string;
}

export const Checkbox = ({
  children,
  value,
  isChecked: isCheckedProp,
  onChange,
  className,
  isDisabled: isDisabledProp,
  isInvalid,
  ...props
}: ICheckboxProps) => {
  const groupContext = useContext(CheckboxGroupContext);
  const [internalChecked, setInternalChecked] = useState(false);

  const isDisabled = isDisabledProp || groupContext?.isDisabled || false;

  const isChecked = groupContext
    ? groupContext.values.includes(value)
    : isCheckedProp !== undefined
      ? isCheckedProp
      : internalChecked;

  const handlePress = () => {
    if (isDisabled) return;

    if (groupContext) {
      groupContext.onValueChange(value);
    } else {
      const next = !isChecked;
      if (isCheckedProp === undefined) setInternalChecked(next);
      onChange?.(next);
    }
  };

  const contextValue = useMemo(
    () => ({
      isChecked,
      isDisabled,
      isInvalid,
    }),
    [isChecked, isDisabled, isInvalid],
  );

  return (
    <CheckboxContext.Provider value={contextValue}>
      <Pressable
        onPress={handlePress}
        disabled={isDisabled}
        accessibilityRole="checkbox"
        accessibilityState={{
          checked: isChecked,
          disabled: isDisabled,
        }}
        className={`flex-row items-center py-2 active:opacity-80 ${className || ''}`}
        {...props}
      >
        {children}
      </Pressable>
    </CheckboxContext.Provider>
  );
};

export const CheckboxGroup = ({
  children,
  value = [],
  onChange,
  isDisabled,
  className,
  ...props
}: {
  children: React.ReactNode;
  value?: string[];
  onChange?: (values: string[]) => void;
  isDisabled?: boolean;
  className?: string;
} & ViewProps) => {
  const handleValueChange = (val: string) => {
    if (isDisabled) return;

    const nextValue = value.includes(val) ? value.filter((v) => v !== val) : [...value, val];
    onChange?.(nextValue);
  };

  const contextValue = useMemo(
    () => ({
      values: value,
      onValueChange: handleValueChange,
      isDisabled,
    }),
    [value, isDisabled, handleValueChange],
  );

  return (
    <CheckboxGroupContext.Provider value={contextValue}>
      <View {...props} className={`${className || ''}`}>
        {children}
      </View>
    </CheckboxGroupContext.Provider>
  );
};

Checkbox.displayName = 'Checkbox';
CheckboxGroup.displayName = 'CheckboxGroup';

export { Checkbox as default };

