    const iconSize = typeof size === 'number' ? size : sizeMap[size] || 20;
    const Component = As as any;

    return (
      <Component
        {...props}
        ref={ref}
        size={iconSize}
        color={color}
        fill={fill}
        strokeWidth={strokeWidth}
        className={className}
        style={style}
        // Modern Accessibility
        aria-hidden="true"
        focusable={false}
      />
    );
  },
);

