            className="w-full max-w-[500px]"
            accessibilityRole="alert"
            accessibilityViewIsModal={true}
          >
            <Box className="bg-phase-elevated rounded-3xl overflow-hidden shadow-2xl border border-phase-interactive/10">
              {children}
