      console.warn('[FidelityProvider] Save error:', e);
    }
  }, []);

  const value = useMemo(
    () => ({
      fidelityLevel,
      effectiveFidelity,
      setFidelityLevel,
    }),
    [fidelityLevel, effectiveFidelity, setFidelityLevel],
  );

  return <FidelityContext.Provider value={value}>{children}</FidelityContext.Provider>;
