import NetInfo from '@react-native-community/netinfo';
import { useStore } from '@repo/core/logic';
import {
  createContext,
  type ReactNode,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useState,
} from 'react';
import { AppState, type AppStateStatus } from 'react-native';
import type { NetworkQuality, RealityState } from './types';
import { detectDeviceTier, detectNetworkQuality, shouldUseDataSaver } from './utils';

interface RealityContextValue {
  reality: RealityState;
  refreshReality: () => Promise<void>;
}

const RealityContext = createContext<RealityContextValue | undefined>(undefined);

export function RealityProvider({ children }: { children: ReactNode }) {
  const [reality, setReality] = useState<RealityState>({
    deviceTier: 'medium',
    totalMemoryGB: 4,
    networkQuality: 'good',
    isDataSaverMode: false,
    isBatterySaverMode: false,
  });

  const refreshReality = useCallback(async () => {
    try {
      const [deviceInfo, networkQuality] = await Promise.all([
        detectDeviceTier(),
        detectNetworkQuality(),
      ]);

      setReality((prev) => ({
        ...prev,
        deviceTier: deviceInfo.tier,
        totalMemoryGB: deviceInfo.memoryGB,
        networkQuality,
        isDataSaverMode: shouldUseDataSaver(networkQuality),
      }));
    } catch (error) {
      console.warn('[RealityProvider] Sync error:', error);
    }
  }, []);

  // Network Monitoring
  useEffect(() => {
    const unsubscribe = NetInfo.addEventListener((state: any) => {
      let quality: NetworkQuality = 'offline';
      if (state.isConnected) {
        const type = state.type;
        const details = state.details as any;
        if (type === 'cellular') {
          const gen = details?.cellularGeneration;
          if (gen === '5g') quality = 'excellent';
          else if (gen === '4g') quality = 'good';
          else if (gen === '3g') quality = 'fair';
          else quality = 'poor';
        } else if (type === 'wifi') quality = 'good';
        else quality = 'fair';
      }

      setReality((prev) => ({
        ...prev,
        networkQuality: quality,
        isDataSaverMode: shouldUseDataSaver(quality),
      }));

      // Update core store for connectivity status
      useStore.getState().setIsOnline(state.isConnected ?? false);
    });

    return unsubscribe;
  }, []);

  // App State Monitoring
  useEffect(() => {
    const subscription = AppState.addEventListener('change', (nextAppState: AppStateStatus) => {
      if (nextAppState === 'active') refreshReality();
    });
    return () => subscription.remove();
  }, [refreshReality]);

  // Initial Reality Check
  useEffect(() => {
    refreshReality();
  }, [refreshReality]);

  const value = useMemo(() => ({ reality, refreshReality }), [reality, refreshReality]);

  return <RealityContext.Provider value={value}>{children}</RealityContext.Provider>;
}

export function useReality() {
  const context = useContext(RealityContext);
  if (!context) throw new Error('useReality must be used within a RealityProvider');
  return context;
}

import AsyncStorage from '@react-native-async-storage/async-storage';
import { useStore } from '@repo/core/logic';
import {
  createContext,
  type ReactNode,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useState,
} from 'react';
import { useColorScheme } from 'react-native';
import type { TemporalPhase, ThemeMode } from './types';
import { getTemporalPhase, shouldUseDarkTheme } from './utils';

interface ThemeContextValue {
  themeMode: ThemeMode;
  temporalPhase: TemporalPhase;
  isDark: boolean;
  isVeilActive: boolean;
  enableLivingTheme: boolean;
  setThemeMode: (mode: ThemeMode) => void;
  toggleVeil: () => Promise<void>;
  setEnableLivingTheme: (enabled: boolean) => Promise<void>;
}

const ThemeContext = createContext<ThemeContextValue | undefined>(undefined);

const STORAGE_KEYS = {
  IS_VEIL_ACTIVE: '@gurudevi/is_veil_active',
  ENABLE_LIVING_THEME: '@gurudevi/enable_living_theme',
};

const ENABLE_EXPERIMENTAL_DARK_MODE = typeof __DEV__ !== 'undefined' ? __DEV__ : false;

export function ThemeProvider({ children }: { children: ReactNode }) {
  const themeMode = useStore((state: any) => state.themeMode);
  const setStoredThemeMode = useStore((state: any) => state.setThemeMode);

  const [temporalPhase, setTemporalPhase] = useState<TemporalPhase>(() => getTemporalPhase());
  const [isVeilActive, setIsVeilActive] = useState(false);
  const [enableLivingTheme, setEnableLivingThemeState] = useState<boolean>(true);
  const systemColorScheme = useColorScheme();

  // Derived
  const isDark = useMemo(
    () =>
      ENABLE_EXPERIMENTAL_DARK_MODE &&
      (themeMode === 'dark' ||
        (themeMode === 'system' && systemColorScheme === 'dark') ||
        (themeMode === 'auto' && shouldUseDarkTheme(temporalPhase))),
    [themeMode, systemColorScheme, temporalPhase],
  );

  // Load Persisted
  useEffect(() => {
    async function loadThemeSettings() {
      try {
        const [veil, living] = await Promise.all([
          AsyncStorage.getItem(STORAGE_KEYS.IS_VEIL_ACTIVE),
          AsyncStorage.getItem(STORAGE_KEYS.ENABLE_LIVING_THEME),
        ]);
        if (veil) setIsVeilActive(veil === 'true');
        if (living !== null) setEnableLivingThemeState(living === 'true');
      } catch (e) {
        console.warn('[ThemeProvider] Load error:', e);
      }
    }
    loadThemeSettings();
  }, []);

  // Temporal Sync
  useEffect(() => {
    const update = () => {
      const next = getTemporalPhase();
      setTemporalPhase((prev) => (prev !== next ? next : prev));
    };
    update();
    const interval = setInterval(update, 60000);
    return () => clearInterval(interval);
  }, []);

  const setThemeMode = useCallback(
    (mode: ThemeMode) => {
      setStoredThemeMode(mode);
      if (mode === 'auto') setTemporalPhase(getTemporalPhase());
    },
    [setStoredThemeMode],
  );

  const toggleVeil = useCallback(async () => {
    const newValue = !isVeilActive;
    setIsVeilActive(newValue);
    try {
      await AsyncStorage.setItem(STORAGE_KEYS.IS_VEIL_ACTIVE, String(newValue));
    } catch (e) {
      console.warn('[ThemeProvider] Veil error:', e);
    }
  }, [isVeilActive]);

  const setEnableLivingTheme = useCallback(async (enabled: boolean) => {
    setEnableLivingThemeState(enabled);
    try {
      await AsyncStorage.setItem(STORAGE_KEYS.ENABLE_LIVING_THEME, String(enabled));
    } catch (e) {
      console.warn('[ThemeProvider] Living error:', e);
    }
  }, []);

  const value = useMemo(
    () => ({
      themeMode,
      temporalPhase,
      isDark,
      isVeilActive,
      enableLivingTheme,
      setThemeMode,
      toggleVeil,
      setEnableLivingTheme,
    }),
    [
      themeMode,
      temporalPhase,
      isDark,
      isVeilActive,
      enableLivingTheme,
      setThemeMode,
      toggleVeil,
      setEnableLivingTheme,
    ],
  );

  return <ThemeContext.Provider value={value}>{children}</ThemeContext.Provider>;
}

export function useThemeContext() {
  const context = useContext(ThemeContext);
  if (!context) throw new Error('useThemeContext must be used within a ThemeProvider');
  return context;
}

