import { useEffect, useState, useCallback, useMemo } from 'react';
import { AccessibilityInfo } from 'react-native';

/**
 * useAccessibility Hook
 *
 * Provides real-time access to the device's accessibility settings.
 * Useful for adapting UI/UX for screen readers and reduced motion preferences.
 */
export const useAccessibility = () => {
  const [isScreenReaderEnabled, setIsScreenReaderEnabled] = useState(false);
  const [isReduceMotionEnabled, setIsReduceMotionEnabled] = useState(false);

  useEffect(() => {
    // Handlers
    const handleScreenReaderChange = (enabled: boolean) => {
      setIsScreenReaderEnabled(enabled);
    };

    const handleReduceMotionChange = (enabled: boolean) => {
      setIsReduceMotionEnabled(enabled);
    };

    // Initial checks
    AccessibilityInfo.isScreenReaderEnabled().then(handleScreenReaderChange);
    AccessibilityInfo.isReduceMotionEnabled().then(handleReduceMotionChange);

    // Event Listeners
    const screenReaderSubscription = AccessibilityInfo.addEventListener(
      'screenReaderChanged',
      handleScreenReaderChange,
    );

    const reduceMotionSubscription = AccessibilityInfo.addEventListener(
      'reduceMotionChanged',
      handleReduceMotionChange,
    );

    return () => {
      screenReaderSubscription.remove();
      reduceMotionSubscription?.remove();
    };
  }, []);

  /**
   * Post a string to be announced by the screen reader.
   * @param message The string to announce
   */
  const announce = useCallback((message: string) => {
    AccessibilityInfo.announceForAccessibility(message);
  }, []);

  return useMemo(() => ({
    isScreenReaderEnabled,
    isReduceMotionEnabled,
    announce,
  }), [isScreenReaderEnabled, isReduceMotionEnabled, announce]);
};

import { api, useStore } from '@repo/core/logic';
import { useTranslation } from 'react-i18next';
import { Alert, Platform } from 'react-native';
import { hapticSuccess, hapticWarning } from '../utils/haptics';
import { useCallback, useMemo } from 'react';

/**
 * Hook to handle the "Bridge to Reality" flow when exiting Demo Mode.
 * If the user has performed any simulated writes, it prompts them to save.
 */
export function useDemoBridge() {
  const { t } = useTranslation();
  const { demoLogs, clearDemoLogs, setDemoMode } = useStore() as any;

  /**
   * Processes the shadow logs and executes real API calls.
   */
  const processDemoLogs = useCallback(async (logs: any[]) => {
    console.log(`[DemoBridge] Processing ${logs.length} logs for reality...`);

    for (const log of logs) {
      try {
        const apiModule = (api as any)[log.module];
        if (apiModule && typeof apiModule[log.method] === 'function') {
          console.log(`[DemoBridge] Realizing: ${log.module}.${log.method}`);
          await apiModule[log.method](log.payload);
        }
      } catch (err) {
        console.error(`[DemoBridge] Failed to realize ${log.module}.${log.method}:`, err);
      }
    }
  }, []);

  const exitDemoWithBridge = useCallback(async () => {
    if (demoLogs.length === 0) {
      setDemoMode(false);
      return;
    }

    // Get the name of the first item created for a personalized message
    const firstLog = demoLogs.find(
      (log: any) => log.method.startsWith('create') || log.method.startsWith('add'),
    );
    const firstItemName =
      (firstLog?.payload as any)?.name || (firstLog?.payload as any)?.title || 'item';

    hapticWarning();

    if (Platform.OS === 'web') {
      // Two-action demo bridge - window.confirm is acceptable for this destructive choice on web
      const save = window.confirm(
        t('demoMode.bridgeMessage', {
          count: demoLogs.length,
          firstName: firstItemName,
        }),
      );
      if (save) {
        const { setBridging } = useStore.getState() as any;
        try {
          setBridging(true);
          await processDemoLogs(demoLogs);
          hapticSuccess();
        } finally {
          setBridging(false);
          clearDemoLogs();
          setDemoMode(false);
        }
      } else {
        clearDemoLogs();
        setDemoMode(false);
      }
      return;
    }

    Alert.alert(
      t('demoMode.bridgeTitle'),
      t('demoMode.bridgeMessage', {
        count: demoLogs.length,
        firstName: firstItemName,
      }),
      [
        {
          text: t('demoMode.bridgeDiscard'),
          style: 'destructive',
          onPress: () => {
            clearDemoLogs();
            setDemoMode(false);
          },
        },
        {
          text: t('demoMode.bridgeSave'),
          onPress: async () => {
            const { setBridging } = useStore.getState() as any;
            try {
              // Enable bridging mode to bypass API interception
              setBridging(true);

              // Bridge the data to reality
              await processDemoLogs(demoLogs);

              hapticSuccess();
            } finally {
              setBridging(false);
              clearDemoLogs();
              setDemoMode(false);
            }
          },
        },
      ],
    );
  }, [demoLogs, setDemoMode, clearDemoLogs, t, processDemoLogs]);

  return useMemo(() => ({ exitDemoWithBridge }), [exitDemoWithBridge]);
}

import { useCallback, useState } from 'react';
import { SovereignError } from '@repo/core/lib';
import { useErrorResolution } from '../providers/ErrorResolutionProvider';
import { useToast } from '../providers/ToastProvider';

export interface SafeActionProgress {
  message: string;
  percentage?: number;
  status: 'pending' | 'success' | 'error';
}

interface SafeActionOptions<TResult> {
  successMessage?: string;
  errorMessage?: string;
  onSuccess?: (result: TResult) => void;
  onError?: (error: any) => void;
}

/**
 * Sovereign Action Lifecycle Hook (2026 SAL Standard)
 *
 * Handles idempotency, loading states, and automatic feedback.
 * Now supports real-time progress tracking for Agentic workflows.
 */
export function useSafeAction<TArgs extends any[], TResult>(
  action: (
    utils: { setProgress: (p: SafeActionProgress) => void },
    ...args: TArgs
  ) => Promise<TResult>,
  options: SafeActionOptions<TResult> = {},
) {
  const [isPending, setIsPending] = useState(false);
  const [progress, setProgress] = useState<SafeActionProgress | null>(null);
  const { showToast } = useToast();
  const { resolveError } = useErrorResolution();

  const execute = useCallback(
    async (...args: TArgs) => {
      if (isPending) return;

      setIsPending(true);
      setProgress({ message: 'Initializing...', status: 'pending' });

      try {
        const result = await action({ setProgress }, ...args);

        if (options.successMessage) {
          showToast({
            message: options.successMessage,
            type: 'success',
          });
        }

        setProgress(null); // Clear progress on success unless we want a "Done" state
        options.onSuccess?.(result);
        return result;
      } catch (error: any) {
        setProgress({ 
          message: error?.message || 'Action failed', 
          status: 'error' 
        });

        if (error instanceof SovereignError) {
          resolveError(error);
        } else {
          const message =
            options.errorMessage || error?.message || 'An unexpected error occurred';

          showToast({
            message,
            type: 'error',
          });
        }

        options.onError?.(error);
        throw error;
      } finally {
        setIsPending(false);
      }
    },
    [action, isPending, options, showToast, resolveError],
  );

  return {
    execute,
    isPending,
    progress,
    setProgress,
  };
}

