import type React from 'react';
import { createContext, useCallback, useContext, useMemo, useState } from 'react';
import { ScrollView, Text, View } from 'react-native';
import type { ISovereignError } from '@repo/core/lib';
import { Button, ButtonText } from '../components/ui/button';
import { HStack } from '../components/ui/hstack';
import { VStack } from '../components/ui/vstack';
import { UniversalModal } from '../components/UniversalModal';

interface ErrorResolutionContextType {
  resolveError: (error: ISovereignError) => void;
  dismissError: () => void;
}

const ErrorResolutionContext = createContext<ErrorResolutionContextType | undefined>(undefined);

/**
 * ErrorResolutionProvider (2026 UX Standard)
 *
 * A global orchestrator for structured error recovery.
 * Provides high-fidelity feedback with resolution guides and actionable recovery steps.
 */
export const ErrorResolutionProvider: React.FC<{ children: React.ReactNode }> = ({
  children,
}) => {
  const [activeError, setActiveError] = useState<ISovereignError | null>(null);
  const [showDetails, setShowDetails] = useState(false);

  const resolveError = useCallback((error: ISovereignError) => {
    setActiveError(error);
    setShowDetails(false);
  }, []);

  const dismissError = useCallback(() => {
    setActiveError(null);
    setShowDetails(false);
  }, []);

  const contextValue = useMemo(
    () => ({ resolveError, dismissError }),
    [resolveError, dismissError],
  );

  return (
    <ErrorResolutionContext.Provider value={contextValue}>
      {children}
      <UniversalModal isOpen={!!activeError} onClose={dismissError}>
        {activeError && (
          <View className="flex-1 bg-black/60 items-center justify-center p-4">
            <VStack className="bg-phase-surface w-full max-w-lg rounded-2xl p-6 shadow-2xl border border-phase-interactive/20">
              <HStack className="justify-between items-center mb-4">
                <Text className="text-phase-danger font-bold text-xl tracking-tight">
                  Resolution Required
                </Text>
                <Text className="text-phase-text-secondary text-[10px] opacity-60">
                  {new Date(activeError.timestamp).toLocaleTimeString()}
                </Text>
              </HStack>

              <ScrollView className="max-h-60 mb-6" showsVerticalScrollIndicator={false}>
                <Text className="text-phase-text-primary font-bold text-base mb-1">
                  {activeError.message}
                </Text>
                <Text className="text-phase-text-secondary text-xs mb-4 font-mono opacity-80">
                  Code: {activeError.code}
                </Text>

                <VStack className="bg-phase-interactive/5 p-4 rounded-xl border border-phase-interactive/10">
                  <Text className="text-phase-text-primary font-bold text-sm mb-2">
                    Next Steps:
                  </Text>
                  <Text className="text-phase-text-secondary leading-5">
                    {activeError.guide}
                  </Text>
                </VStack>

                <Button
                  variant="link"
                  onPress={() => setShowDetails(!showDetails)}
                  className="mt-4 self-start p-0"
                >
                  <ButtonText className="text-[10px] text-phase-interactive opacity-60">
                    {showDetails ? 'Hide Technical Details' : 'Show Technical Details'}
                  </ButtonText>
                </Button>

                {showDetails && (
                  <VStack className="mt-4 p-3 bg-black/10 rounded-lg border border-white/5">
                    <Text className="text-[10px] font-bold text-phase-text-primary mb-1 uppercase tracking-widest">
                      Agent Resolution Guide
                    </Text>
                    <Text className="text-[10px] text-phase-text-secondary font-mono leading-4">
                      {activeError.agentGuide || 'No agent resolution provided.'}
                    </Text>
                    {activeError.agentHint && (
                      <HStack className="mt-2 items-center gap-2">
                        <View className="px-1.5 py-0.5 bg-phase-interactive/20 rounded border border-phase-interactive/30">
                          <Text className="text-[8px] font-bold text-phase-interactive">
                            {activeError.agentHint}
                          </Text>
                        </View>
                      </HStack>
                    )}
                  </VStack>
                )}
              </ScrollView>

              <VStack className="gap-3">
                {activeError.actions?.map((action, i) => (
                  <Button
                    key={i}
                    variant={(action.variant as any) || 'solid'}
                    onPress={async () => {
                      await action.onPress();
                      dismissError();
                    }}
                  >
                    <ButtonText>{action.label}</ButtonText>
                  </Button>
                ))}
                <Button variant="outline" onPress={dismissError}>
                  <ButtonText>Dismiss</ButtonText>
                </Button>
              </VStack>

              <HStack className="mt-6 justify-center items-center opacity-40">
                <Text className="text-[10px] text-phase-text-secondary font-mono">
                  TRACE::{activeError.id.toUpperCase()}
                </Text>
              </HStack>
            </VStack>
          </View>
        )}
      </UniversalModal>
    </ErrorResolutionContext.Provider>
  );
};

export const useErrorResolution = () => {
  const context = useContext(ErrorResolutionContext);
  if (!context) {
    throw new Error('useErrorResolution must be used within ErrorResolutionProvider');
  }
  return context;
};

/**
 * QRShareButton - QR code display + share controls.
 *
 * Wraps QRCodeGenerator and adds:
 * - Share Image: captures the QR as PNG via react-native-view-shot, then uses expo-sharing
 * - Copy Link: copies the QR URL to the clipboard via expo-clipboard
 *
 * Optional `shortUrl` prop: if provided, the copied/shared URL is the short URL
 * rather than the full gurudevi://qr?... scheme URL.
 */

import { useRef } from 'react';
import { StyleSheet, TouchableOpacity, type View } from 'react-native';
import { Text, View as PrimitiveView } from '../primitives';
import QRCodeGenerator from '../components/QRCodeGenerator';

const optionalImport = async <T = any>(moduleName: string): Promise<T | null> => {
  try {
    const importer = new Function('moduleName', 'return import(moduleName)') as (
      name: string,
    ) => Promise<T>;
    return await importer(moduleName);
  } catch {
    return null;
  }
};

// Lazy-load optional native integrations so unsupported environments do not crash.
// eslint-disable-next-line @typescript-eslint/no-explicit-any
const loadViewShot = async (): Promise<any> => {
  return optionalImport('react-native-view-shot');
};

const loadSharing = () => optionalImport<any>('expo-sharing');
const loadClipboard = () => optionalImport<any>('expo-clipboard');

interface QRShareButtonProps {
  /** Canonical gurudevi://qr?... URI produced by QRBuilder */
  value: string;
  /** Human-readable label shown below the QR code */
  label?: string;
  /** QR code size in pixels */
  size?: number;
  /** If provided, this URL is copied/shared instead of the scheme URI */
  shortUrl?: string;
  /** Background color for the QR + share block */
  backgroundColor?: string;
  /** Text color for buttons */
  accentColor?: string;
}

export default function QRShareButton({
  value,
  label,
  size = 200,
  shortUrl,
  backgroundColor = '#1a1a2e',
  accentColor = '#f5a623',
}: QRShareButtonProps) {
  const viewRef = useRef<View>(null);
  const shareUrl = shortUrl ?? value;

  const handleShareImage = async () => {
    try {
      const viewShot = await loadViewShot();
      if (!viewShot) {
        console.warn('QRShareButton: react-native-view-shot not available');
        return;
      }

      const Sharing = await loadSharing();
      if (!Sharing) {
        console.warn('QRShareButton: expo-sharing not available');
        return;
      }
      if (!viewRef.current) return;

      const uri = await viewShot.captureRef(viewRef, {
        format: 'png',
        quality: 1,
      });
      if (await Sharing.isAvailableAsync()) {
        await Sharing.shareAsync(uri, {
          mimeType: 'image/png',
          dialogTitle: label ? `Share ${label} QR Code` : 'Share QR Code',
        });
      }
    } catch (err) {
      console.warn('QRShareButton: share image failed', err);
    }
  };

  const handleCopyLink = async () => {
    try {
      const Clipboard = await loadClipboard();
      if (!Clipboard) {
        console.warn('QRShareButton: expo-clipboard not available');
        return;
      }
      await Clipboard.setStringAsync(shareUrl);
    } catch (err) {
      console.warn('QRShareButton: copy link failed', err);
    }
  };

  return (
    <PrimitiveView style={[styles.container, { backgroundColor }]}>
      <PrimitiveView ref={viewRef} collapsable={false} style={[styles.qrWrapper, { backgroundColor }]}>
        <QRCodeGenerator value={value} size={size} label={label} />
      </PrimitiveView>

      <PrimitiveView style={styles.buttonRow}>
        <TouchableOpacity
          onPress={handleShareImage}
          style={[styles.button, { borderColor: accentColor }]}
          accessibilityLabel="Share QR code as image"
        >
          <Text style={[styles.buttonText, { color: accentColor }]}>Share Image</Text>
        </TouchableOpacity>

        <TouchableOpacity
          onPress={handleCopyLink}
          style={[styles.button, { borderColor: accentColor }]}
          accessibilityLabel="Copy QR link to clipboard"
        >
          <Text style={[styles.buttonText, { color: accentColor }]}>Copy Link</Text>
        </TouchableOpacity>
      </PrimitiveView>
    </PrimitiveView>
  );
}

const styles = StyleSheet.create({
  container: {
    alignItems: 'center',
    gap: 16,
    padding: 16,
    borderRadius: 16,
  },
  qrWrapper: {
    padding: 12,
    borderRadius: 12,
  },
  buttonRow: {
    flexDirection: 'row',
    gap: 12,
    width: '100%',
  },
  button: {
    flex: 1,
    borderWidth: 1,
    borderRadius: 10,
    paddingVertical: 10,
    alignItems: 'center',
  },
  buttonText: {
    fontSize: 13,
    fontWeight: '600',
  },
});

