        </VStack>
        <Button onPress={onClose} className="mt-4 bg-phase-surface h-14 rounded-2xl">
          <ButtonText className="text-phase-primary font-bold">Close</ButtonText>
        </Button>
      </Box>
    </Box>
  );
});

