// TYPES & REDUCER
// ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

interface OnboardingState {
  currentStep: number;
  name: string;
  authority: AuthorityTier;
  isCompleting: boolean;
  completionError: string | null;
}

type OnboardingAction =
  | { type: 'SET_STEP'; step: number }
  | { type: 'SET_NAME'; name: string }
  | { type: 'SET_AUTHORITY'; authority: AuthorityTier }
  | { type: 'SET_COMPLETING'; isCompleting: boolean }
  | { type: 'SET_ERROR'; error: string | null }
  | { type: 'NEXT_STEP' }
  | { type: 'PREV_STEP' }
  | { type: 'RESTORE_PROGRESS'; progress: Partial<OnboardingState> };

function onboardingReducer(state: OnboardingState, action: OnboardingAction): OnboardingState {
  switch (action.type) {
    case 'SET_STEP':
      return { ...state, currentStep: action.step };
    case 'SET_NAME':
      return { ...state, name: action.name };
    case 'SET_AUTHORITY':
      return { ...state, authority: action.authority };
    case 'SET_COMPLETING':
      return { ...state, isCompleting: action.isCompleting };
    case 'SET_ERROR':
      return { ...state, completionError: action.error };
    case 'NEXT_STEP':
      return { ...state, currentStep: Math.min(6, state.currentStep + 1) };
    case 'PREV_STEP':
      return { ...state, currentStep: Math.max(0, state.currentStep - 1) };
    case 'RESTORE_PROGRESS':
      return { ...state, ...action.progress };
    default:
      return state;
  }
}

