import { coreRuntime } from '@repo/core/logic';

export enum PerformanceTier {
  HIGH = 'HIGH',
  MID = 'MID',
  LOW = 'LOW',
}

/**
 * Heuristic to determine device performance tier
 * This can be refined with specific device model checks
 */
export const getDeviceTier = (): PerformanceTier => {
  try {
    const metadata = coreRuntime.device.getMetadata();
    const { platform, osVersion, modelName } = metadata;

    // 1. Web is generally treated as HIGH or MID depending on modern browser features
    // but for simplicity in this isomorphic layer, we default to MID or HIGH.
    if (platform === 'web') return PerformanceTier.HIGH;

    // 2. iOS Devices
    if (platform === 'ios') {
      // iPhone 11 (iPhone12,1) or newer is High
      if (modelName?.startsWith('iPhone')) {
        const versionMatch = modelName.match(/iPhone(\d+)/);
        if (versionMatch?.[1]) {
          const version = parseInt(versionMatch[1], 10);
          if (version >= 12) return PerformanceTier.HIGH; // iPhone 11+
          if (version >= 10) return PerformanceTier.MID; // iPhone 8/X/XS
          return PerformanceTier.LOW;
        }
      }
      return PerformanceTier.HIGH; // Default for newer iPads/unknown
    }

    // 3. Android Devices
    if (platform === 'android') {
      // On Android, we'd ideally check RAM, but since we've abstracted to Metadata,
      // we'll use a conservative MID fallback or deeper model check if needed.
      return PerformanceTier.MID;
    }
  } catch {
    // Fail safe
  }

  return PerformanceTier.MID;
};

export const DEVICE_TIER = getDeviceTier();
export const IS_LOW_POWER_MODE = DEVICE_TIER === PerformanceTier.LOW;

import { coreRuntime } from '@repo/core/logic';

/**
 * SanctuaryLocation (Native)
 * Wraps coreRuntime.location for cross-platform safety.
 */
export const SanctuaryLocation = {
  requestPermissionsAsync: async () => {
    return await coreRuntime.location.requestPermissionsAsync();
  },
  watchPositionAsync: async (options: any, callback: any) => {
    return await coreRuntime.location.watchPositionAsync(options, callback);
  },
  Accuracy: coreRuntime.location.Accuracy,
};

// Types can be locally defined or shared in @repo/core/types if needed
// For now, we'll use 'any' or basic interfaces if we don't want to export them from Location.
export type LocationSubscription = { remove: () => void };
export type LocationObject = any;

/**
 * SanctuaryLocation (Web)
 *
 * High-fidelity web-native implementation for location services.
 * Uses the native Permissions API and Geolocation API.
 * Avoids importing expo-location to prevent packaging errors.
 */

export const SanctuaryLocation = {
  requestPermissionsAsync: async () => {
    if (!navigator.permissions) {
      return { status: 'granted' as const }; // Fallback for older browsers
    }

    try {
      const status = await navigator.permissions.query({ name: 'geolocation' });
      return {
        status: (status.state === 'granted' ? 'granted' : 'denied') as 'granted' | 'denied',
      };
    } catch (_e) {
      return { status: 'denied' as const };
    }
  },
  watchPositionAsync: async (options: any, callback: any) => {
    if (!navigator.geolocation) return { remove: () => {} };

    const watchId = navigator.geolocation.watchPosition(
      (pos) => {
        callback({
          coords: {
            latitude: pos.coords.latitude,
            longitude: pos.coords.longitude,
            altitude: pos.coords.altitude,
            accuracy: pos.coords.accuracy,
            altitudeAccuracy: null,
            heading: pos.coords.heading,
            speed: pos.coords.speed,
          },
          timestamp: pos.timestamp,
        });
      },
      (err) => console.warn('Geolocation error:', err),
      {
        enableHighAccuracy: options.accuracy >= 3,
        timeout: options.timeInterval || 5000,
        maximumAge: 0,
      },
    );

    return {
      remove: () => navigator.geolocation.clearWatch(watchId),
    };
  },
  Accuracy: {
    Lowest: 1,
    Low: 2,
    Balanced: 3,
    High: 4,
    Highest: 5,
    BestForNavigation: 6,
  },
};

export type LocationSubscription = {
  remove: () => void;
};

export type LocationObject = {
  coords: {
    latitude: number;
    longitude: number;
    altitude: number | null;
    accuracy: number | null;
    altitudeAccuracy: number | null;
    heading: number | null;
    speed: number | null;
  };
  timestamp: number;
};

const {
  compositeColorOverBackground,
  getContrastRatio,
  getAccessibleTextColor,
} = require('../colorUtils');
const { checkAccessibility } = require('../a11yUtils');
const { resolvePhaseTokens } = require('../../theme/Theme');

describe('Accessibility Audit - scene and accent contrast', () => {
  const phases = ['predawn', 'dawn', 'morning', 'afternoon', 'dusk', 'night'];
  const modes = ['light', 'dark'];
  const AA_THRESHOLD = 4.5;

  const resolveSceneBackground = (tokens, layerName) => {
    switch (layerName) {
      case 'world':
        return tokens.scene.world.bg;
      case 'chrome':
        return compositeColorOverBackground(tokens.scene.chrome.bg, tokens.scene.world.bg);
      case 'canvas':
        return tokens.scene.canvas.bg;
      case 'surface':
        return compositeColorOverBackground(tokens.scene.surface.bg, tokens.scene.canvas.bg);
      case 'elevated':
        return compositeColorOverBackground(tokens.scene.elevated.bg, tokens.scene.canvas.bg);
      case 'interactive':
        return compositeColorOverBackground(tokens.scene.interactive.bg, tokens.scene.surface.bg);
      default:
        throw new Error(`Unknown scene layer: ${layerName}`);
    }
  };

  describe('Accent backgrounds', () => {
    phases.forEach((phase) => {
      modes.forEach((mode) => {
        it(`[${phase}/${mode}] action accent meets AA`, () => {
          const tokens = resolvePhaseTokens(phase, mode === 'dark');
          const ratio = getContrastRatio(tokens.text.onAccent, tokens.accent.action);

          expect(ratio).toBeGreaterThanOrEqual(AA_THRESHOLD);
        });

        it(`[${phase}/${mode}] danger accent meets AA`, () => {
          const tokens = resolvePhaseTokens(phase, mode === 'dark');
          const ratio = getContrastRatio(tokens.text.onDanger, tokens.accent.danger);

          expect(ratio).toBeGreaterThanOrEqual(AA_THRESHOLD);
        });
      });
    });
  });

  describe('Scene layer text pairings', () => {
    phases.forEach((phase) => {
      modes.forEach((mode) => {
        it(`[${phase}/${mode}] text.onWorld meets AA`, () => {
          const tokens = resolvePhaseTokens(phase, mode === 'dark');
          const ratio = getContrastRatio(
            tokens.text.onWorld,
            resolveSceneBackground(tokens, 'world'),
          );

          expect(ratio).toBeGreaterThanOrEqual(AA_THRESHOLD);
        });

        it(`[${phase}/${mode}] text.onChrome meets AA`, () => {
          const tokens = resolvePhaseTokens(phase, mode === 'dark');
          const ratio = getContrastRatio(
            tokens.text.onChrome,
            resolveSceneBackground(tokens, 'chrome'),
          );

          expect(ratio).toBeGreaterThanOrEqual(AA_THRESHOLD);
        });

        it(`[${phase}/${mode}] text.onCanvas meets AA`, () => {
          const tokens = resolvePhaseTokens(phase, mode === 'dark');
          const ratio = getContrastRatio(
            tokens.text.onCanvas,
            resolveSceneBackground(tokens, 'canvas'),
          );

          expect(ratio).toBeGreaterThanOrEqual(AA_THRESHOLD);
        });

        it(`[${phase}/${mode}] text.onSurface meets AA`, () => {
          const tokens = resolvePhaseTokens(phase, mode === 'dark');
          const ratio = getContrastRatio(
            tokens.text.onSurface,
            resolveSceneBackground(tokens, 'surface'),
          );

          expect(ratio).toBeGreaterThanOrEqual(AA_THRESHOLD);
        });

        it(`[${phase}/${mode}] text.onElevated meets AA`, () => {
          const tokens = resolvePhaseTokens(phase, mode === 'dark');
          const ratio = getContrastRatio(
            tokens.text.onElevated,
            resolveSceneBackground(tokens, 'elevated'),
          );

          expect(ratio).toBeGreaterThanOrEqual(AA_THRESHOLD);
        });

        it(`[${phase}/${mode}] text.onInteractive meets AA`, () => {
          const tokens = resolvePhaseTokens(phase, mode === 'dark');
          const ratio = getContrastRatio(
            tokens.text.onInteractive,
            resolveSceneBackground(tokens, 'interactive'),
          );

          expect(ratio).toBeGreaterThanOrEqual(AA_THRESHOLD);
        });
      });
    });
  });

  describe('APCA spot checks', () => {
    it('scene canvas text meets APCA body recommendation', () => {
      const tokens = resolvePhaseTokens('morning', false);
      const { apca } = checkAccessibility(tokens.text.onCanvas, tokens.scene.canvas.bg);

      expect(Math.abs(apca)).toBeGreaterThanOrEqual(60);
    });
  });

  describe('Readable text helper', () => {
    it('selects a dark text color for white-ish backgrounds', () => {
      const result = getAccessibleTextColor('#FFFFFF');

      expect(result.color).toBe('#2A2318');
      expect(result.passesAA).toBe(true);
    });

    it('still returns a candidate for difficult mid-tone backgrounds', () => {
      const result = getAccessibleTextColor('#888888');

      expect(result.ratio).toBeGreaterThan(1);
    });
  });
});
